import type { T, Lang } from './lang';
import { moreGuide } from './guides-more';

// The guides at /learn: short, plain pages on the things a race is won by, each ending in the game, where you can try
// it. Written for people who search for them (and for the AI assistants that answer them), so each one teaches the
// thing itself and not just the game. Every claim about the game is what it does (public/game/sim.js, main.js); change
// the game, change the guide.
export type Guide = {
  slug: string; title: string; short: string; description: string; kicker: string; intro: string;
  // a picture from the game (public/images) on the guide's card and behind its head, where one fits: the downwind
  // guide has none, as no picture of the game shows a run
  img?: { src: string; width: number; height: number; alt: string };
  // each section's tip is a callout under its text, in your blue; pen: it's about a foul or a penalty, in the umpire's
  // red. fig: the drawing under the text (components/guide-figure.tsx)
  sections: { id: string; h: string; p: string[]; tip?: string; pen?: true; fig?: 'wide' }[];
  more: { label: string; href: string }[]; // further reading
  try: { label: string; href: string; text: string };
};

// the rules guide on the Sailing Certification Test site, rule by rule
const rr = (lang: Lang, page: string) => `https://iyt.rycrentals.com${lang === 'ru' ? '/ru' : ''}/racing-rules/${page}`;

// the basics first (points of sail, tacking and gybing: lib/guides-more.ts), then the race from the rules to boat speed
export const GUIDES = ['sail', 'tack', 'rules', 'start', 'shifts', 'marks', 'downwind', 'trim'] as const;
export type GuideSlug = (typeof GUIDES)[number];
// when each guide was first published and last changed in substance: its byline, its Article data and the sitemap
export const GUIDE_DATES: Record<GuideSlug, { published: string; modified: string }> = {
  sail: { published: '2026-11-17', modified: '2026-11-17' }, tack: { published: '2026-11-17', modified: '2026-11-17' },
  rules: { published: '2026-11-14', modified: '2026-11-18' }, start: { published: '2026-11-14', modified: '2026-11-18' },
  shifts: { published: '2026-11-14', modified: '2026-11-14' }, marks: { published: '2026-11-14', modified: '2026-11-14' },
  downwind: { published: '2026-11-14', modified: '2026-11-14' }, trim: { published: '2026-11-14', modified: '2026-11-14' },
};
export const isGuide = (s: string): s is GuideSlug => (GUIDES as readonly string[]).includes(s);
// its number, as the card and the head say it: "Guide 6 of 8"
export const guideNo = (slug: GuideSlug) => GUIDES.indexOf(slug) + 1;

// the game's pictures, 1920 × 1440 unless said
const shot = (src: string, alt: string, width = 1920, height = 1440) => ({ src: `/images/${src}.jpg`, width, height, alt });

export function guide(slug: GuideSlug, t: T, lang: Lang): Guide {
  if (slug === 'sail' || slug === 'tack') return moreGuide(slug, t, lang);
  if (slug === 'marks') return {
    slug,
    title: t('Rounding the marks: the windward mark and the gate', 'Огибание знаков: верхний знак и ворота', 'Redondear las balizas: la baliza de barlovento y la puerta', 'Die Bahnmarken runden: die Luvtonne und das Tor', 'Şamandıraları dönmek: rüzgârüstü şamandırası ve kapı', 'Passer les bouées : la bouée au vent et la porte'),
    short: t('Rounding the marks', 'Огибание знаков', 'Redondear las balizas', 'Die Bahnmarken runden', 'Şamandıraları dönmek', 'Passer les bouées'),
    kicker: t('Racing guides · marks', 'Пособия по гонкам · знаки', 'Guías de regata · balizas', 'Regattaleitfäden · Bahnmarken', 'Yarış rehberleri · şamandıralar', 'Guides de régate · bouées'),
    img: shot('gd-marks-v2', t('Your boat rounding the windward mark in the game, with yachts close on either side', 'Твоя лодка огибает верхний знак в игре, рядом идут другие яхты', 'Tu barco redondeando la baliza de barlovento en el juego, con yates muy cerca a ambos lados', 'Dein Boot rundet im Spiel die Luvtonne, Yachten dicht auf beiden Seiten', 'Oyunda rüzgârüstü şamandırasını dönen teknen, iki yanında yatlar', 'Ton bateau passant la bouée au vent dans le jeu, des yachts au contact de chaque côté'), 3840, 1600),
    description: t(
      'How to round the marks in a sailboat race: approaching the windward mark on the starboard layline, the bear-away, choosing a side of the leeward gate, wide in and tight out, room in the zone and touching a mark.',
      'Как огибать знаки в парусной гонке: подход к верхнему знаку по лейлайну правого галса, поворот на попутный курс, выбор знака в нижних воротах, «широко зайти — узко выйти», место в зоне и касание знака.', 'Cómo redondear las balizas en una regata de vela: acercarse a la baliza de barlovento por la layline de estribor, el arribar, elegir un lado de la puerta de sotavento, abierto al entrar y cerrado al salir, espacio en la zona y tocar una baliza.', 'So rundest du die Bahnmarken in einer Segelregatta: Anliegen der Luvtonne auf der Steuerbord-Layline, das Abfallen, die Wahl einer Seite des Leetors, weit hinein und eng hinaus, Raum in der Zone und das Berühren einer Bahnmarke.', 'Yelken yarışında şamandıralar nasıl dönülür: rüzgârüstü şamandırasına sancak layline’dan yaklaşmak, boşlama, rüzgâraltı kapısında taraf seçmek, geniş girip dar çıkmak, bölgede alan ve şamandıraya dokunmak.', 'Comment passer les bouées en régate : arriver à la bouée au vent sur la lay-line tribord, l’abattée, choisir un côté de la porte sous le vent, large en entrée et serré en sortie, la place dans la zone et toucher une bouée.'),
    intro: t(
      'Boats bunch up at the marks, so places are won and lost there more than anywhere else on the course. A clean rounding is mostly a matter of arriving on the right tack, at the right angle, with the rules on your side.',
      'У знаков лодки сходятся вместе, и места там выигрывают и проигрывают чаще, чем где-либо на дистанции. Чистое огибание — это прежде всего прийти правильным галсом, под правильным углом и с правилами на своей стороне.', 'Los barcos se agrupan en las balizas, así que se ganan y se pierden puestos allí más que en cualquier otro sitio del recorrido. Un buen redondeo es sobre todo llegar por la amura adecuada, con el ángulo adecuado y con las reglas de tu parte.', 'An den Bahnmarken drängen sich die Boote, deshalb werden dort mehr Plätze gewonnen und verloren als irgendwo sonst auf der Bahn. Eine saubere Rundung heißt vor allem: auf dem richtigen Bug, im richtigen Winkel ankommen und die Regeln auf deiner Seite haben.', 'Tekneler şamandıralarda kümelenir; bu yüzden sıralar parkurun başka hiçbir yerinde değil, burada kazanılır ya da kaybedilir. Temiz bir dönüş çoğunlukla doğru kontrada, doğru açıyla ve kurallar senden yanayken gelmekle ilgilidir.', 'Les bateaux se regroupent aux bouées : c’est là, plus que partout ailleurs sur le parcours, que les places se gagnent et se perdent. Un passage propre, c’est surtout arriver sur le bon bord, avec le bon angle et les règles de ton côté.'),
    sections: [
      { id: 'approach', h: t('Come in on starboard', 'Подходи правым галсом', 'Entra por estribor', 'Komm auf Steuerbord an', 'Sancakta gel', 'Arrive tribord amures'), p: [
        t('The windward mark is usually left to port, so the last tack into it is on starboard, and a starboard boat has right of way over anyone coming in on port (rule 10). Coming in on port means ducking the starboard boats or tacking under them in the zone — where you must not make a boat that has been on starboard since entering the zone sail above close-hauled (rule 18.3).',
          'Верхний знак обычно оставляют слева, поэтому последний галс к нему — правый, а лодка правого галса имеет право дороги над всеми, кто идёт левым (правило 10). Подходить левым — значит проходить за кормой лодок правого галса или поворачивать под ними в зоне, где нельзя заставить лодку, идущую правым галсом с момента входа в зону, идти круче бейдевинда (правило 18.3).', 'La baliza de barlovento se deja normalmente por babor, así que la última virada hacia ella es por estribor, y un barco de estribor tiene derecho de paso sobre cualquiera que entre por babor (regla 10). Entrar por babor significa pasar por popa de los de estribor o virar bajo ellos en la zona — donde no debes obligar a un barco que va por estribor desde que entró en la zona a navegar por encima de la ceñida (regla 18.3).', 'Die Luvtonne wird meist an Backbord gelassen, deshalb liegt der letzte Schlag darauf auf Steuerbord, und ein Boot auf Steuerbord hat Wegerecht gegenüber jedem, der auf Backbord ankommt (Regel 10). Auf Backbord anzukommen heißt, den Steuerbordbooten hinten durchzugehen oder unter ihnen zu wenden, in der Zone, wo du ein Boot, das seit dem Erreichen der Zone auf Steuerbord segelt, nicht zwingen darfst, höher als hoch am Wind zu segeln (Regel 18.3).', 'Rüzgârüstü şamandırası genellikle iskelede bırakılır; bu yüzden ona son tramola sancakta olur ve sancaktaki tekne, iskeleden gelen herkese karşı geçiş hakkına sahiptir (kural 10). İskeleden gelmek, sancaktaki teknelerin arkasından geçmek ya da bölgede onların altından tramola atmak demektir. Orada bölgeye girdiğinden beri sancakta olan bir tekneyi orsadan daha yukarı yelken açmaya zorlamamalısın (kural 18.3).', 'La bouée au vent se laisse en général à bâbord : le dernier bord pour y arriver est donc tribord amures, et un bateau tribord amures a priorité sur tout bateau qui arrive bâbord amures (règle 10). Arriver bâbord amures, c’est passer derrière les tribord ou virer sous leur vent dans la zone — où tu ne dois pas obliger un bateau qui est tribord amures depuis son entrée dans la zone à naviguer au-dessus du près serré (règle 18.3).'),
        t('Don’t overstand: tack onto the layline late enough that a shift can’t leave you sailing extra distance, but early enough not to be stuck below it in a crowd.',
          'Не перебирай: выходи на лейлайн достаточно поздно, чтобы сдвиг ветра не заставил идти лишнее, но достаточно рано, чтобы не застрять под ним в толпе.', 'No te pases: vira a la layline lo bastante tarde para que una rolada no te deje navegando distancia de más, pero lo bastante pronto para no quedarte por debajo de ella en medio del grupo.', 'Nicht überstehen: Wende auf die Layline spät genug, dass ein Winddreher dich nicht auf einen Umweg schickt, aber früh genug, dass du nicht im Gedränge darunter festsitzt.', 'Layline’dan öteye geçme: tramolayı layline’da bir rüzgâr dönüşünün seni fazladan yol yaptırmayacağı kadar geç, ama kalabalıkta onun altında sıkışıp kalmayacağın kadar erken at.', 'Ne dépasse pas la lay-line : vire dessus assez tard pour qu’une bascule ne te fasse pas parcourir de la distance en trop, mais assez tôt pour ne pas rester coincé en dessous dans la foule.'),
      ], tip: t('Coming in on port in a crowd? Duck the starboard boats and tack onto the layline behind them, outside the zone, rather than in front of them inside it.',
        'Подходишь левым галсом в толпе? Пройди за кормой лодок правого галса и поверни на лейлайн позади них, ещё до зоны, а не перед ними внутри неё.', '¿Entras por babor en medio del grupo? Pasa por popa de los de estribor y vira a la layline detrás de ellos, fuera de la zona, en lugar de delante de ellos dentro de ella.', 'Auf Backbord im Gedränge? Geh den Steuerbordbooten hinten durch und wende hinter ihnen auf die Layline, außerhalb der Zone, statt vor ihnen innerhalb.', 'İskelede kalabalığa mı giriyorsun? Sancaktaki teknelerin arkasından geç ve layline’a bölgenin dışında, onların önünde değil arkasında tramola atarak çık; bölgenin içinde onların önüne geçmeye çalışma.', 'Tu arrives bâbord amures dans la foule ? Passe derrière les tribord et vire sur la lay-line derrière eux, hors de la zone, plutôt que devant eux à l’intérieur.') },
      { id: 'bear', h: t('The bear-away', 'Поворот на попутный', 'El arribar', 'Das Abfallen', 'Boşlama', 'L’abattée'), p: [
        t('Round close to the mark, then bear away smoothly onto the run, easing the sheets as you turn, and hoist the gennaker once you are clear and pointing down the course. Hoisting takes the crew a few seconds, so don’t ask for it in the middle of the turn.',
          'Обогни знак вплотную, плавно увались на попутный курс, потравливая шкоты по ходу поворота, и ставь генакер, когда отошёл от знака и смотришь вниз по дистанции. Постановка занимает у команды несколько секунд, так что не проси её посреди поворота.', 'Redondea cerca de la baliza, luego arriba con suavidad hacia la empopada, soltando las escotas al girar, e iza el gennaker cuando estés libre y apuntando por el recorrido. Izar le lleva a la tripulación unos segundos, así que no lo pidas en mitad del giro.', 'Runde dicht an der Bahnmarke, falle dann weich auf den Vorwindkurs ab, fiere dabei die Schoten und setze den Gennaker, sobald du frei bist und die Bahn hinunter zeigst. Das Setzen dauert für die Crew ein paar Sekunden, verlange es also nicht mitten in der Drehung.', 'Şamandıraya yakın dön, sonra dönerken iskotaları boşaltarak pupaya doğru yumuşakça boşla; açıkta kalıp parkurun aşağısına baktığında gennakeri çek. Çekmek mürettebatın birkaç saniyesini alır, o yüzden dönüşün ortasında isteme.', 'Passe près de la bouée, puis abats en douceur vers le vent arrière en choquant les écoutes pendant le virage, et envoie le gennaker une fois dégagé et le cap sur le parcours. L’envoi prend quelques secondes à l’équipage : ne le demande pas au milieu du virage.'),
      ], tip: t('Round half a boat length off the mark: close enough to lose nothing, far enough that a wave or a late turn won’t put you on it, and into a penalty turn.',
        'Огибай в половине корпуса от знака: достаточно близко, чтобы ничего не терять, и достаточно далеко, чтобы волна или запоздалый поворот не бросили тебя на него — и на штрафной оборот.', 'Rodea a media eslora de la baliza: lo bastante cerca para no perder nada, lo bastante lejos para que una ola o un giro tardío no te echen encima, con giro de penalización.', 'Runde eine halbe Bootslänge von der Bahnmarke entfernt: nah genug, um nichts zu verlieren, weit genug, dass dich eine Welle oder eine späte Drehung nicht auf sie setzt und in einen Strafkringel zwingt.', 'Şamandıradan yarım tekne boyu açıkta dön: hiçbir şey kaybetmeyecek kadar yakın, ama bir dalga ya da geç bir dönüş seni ona çarptırıp ceza dönüşüne sokmayacak kadar uzak.', 'Passe à une demi-longueur de la bouée : assez près pour ne rien perdre, assez loin pour qu’une vague ou un virage tardif ne te jette pas dessus, et dans un tour de pénalité.') },
      { id: 'gate', h: t('Pick a side of the gate', 'Выбери знак в воротах', 'Elige un lado de la puerta', 'Wähle eine Seite des Tors', 'Kapıda taraf seç', 'Choisis un côté de la porte'), p: [
        t('At the bottom of the run, a gate gives you two marks to choose from: sail between them and round either one. Take the one further upwind, which shortens the next beat, or the one that sends you towards the side of the course you want — and the one with fewer boats queuing for it.',
          'В конце попутного ворота дают выбор из двух знаков: пройди между ними и обогни любой. Бери тот, что ближе к ветру, — следующая лавировка станет короче, — или тот, что уводит на нужную сторону дистанции, и тот, у которого меньше очередь.', 'Al final de la empopada, una puerta te da dos balizas entre las que elegir: pasa entre ellas y redondea cualquiera de las dos. Toma la más a barlovento, que acorta la siguiente ceñida, o la que te lleva hacia el lado del recorrido que quieres, y la que tenga menos barcos haciendo cola.', 'Am Ende des Vorwindkurses bietet dir das Tor zwei Bahnmarken zur Wahl: Segle zwischen ihnen hindurch und runde eine von beiden. Nimm die weiter in Luv liegende, das verkürzt das nächste Kreuz, oder die, die dich zur gewünschten Seite der Bahn schickt, und die, an der sich weniger Boote anstellen.', 'Pupa ayağının sonunda kapı sana seçecek iki şamandıra verir: ikisinin arasından geç ve birinin etrafından dön. Daha rüzgârüstündekini al, bu bir sonraki orsa ayağını kısaltır; ya da parkurda istediğin tarafa götürenini ve önünde daha az teknenin sıraya girdiğini seç.', 'Au bas du bord de portant, une porte te laisse le choix entre deux bouées : passe entre elles et contourne l’une ou l’autre. Prends la plus au vent, qui raccourcit le bord de près suivant, ou celle qui t’envoie du côté du plan d’eau que tu veux — et celle où moins de bateaux font la queue.'),
        t('Drop the gennaker a few lengths before the mark, so the crew is ready to trim upwind as you round.',
          'Убирай генакер за несколько корпусов до знака, чтобы команда успела подготовиться к лавировке.', 'Arría el gennaker unas esloras antes de la baliza, para que la tripulación esté lista para trimar de ceñida al redondearla.', 'Berge den Gennaker einige Längen vor der Bahnmarke, damit die Crew beim Runden bereit ist, am Wind zu trimmen.', 'Gennakeri şamandıradan birkaç boy önce indir; dönerken mürettebat orsaya trim etmeye hazır olsun.', 'Affale le gennaker quelques longueurs avant la bouée, pour que l’équipage soit prêt à régler au près au moment du passage.'),
      ], tip: t('Pick your gate mark a good few lengths before the zone, so you can swing wide for it. A late change of mind means a tight turn and coming out wide.',
        'Выбери знак в воротах за несколько корпусов до зоны, чтобы успеть зайти к нему широко. Передумаешь поздно — получится крутой поворот и широкий выход.', 'Elige la baliza de la puerta bastantes esloras antes de la zona, para poder abrirte hacia ella. Cambiar de idea tarde significa un giro cerrado y salir abierto.', 'Such dir deine Tormarke gut ein paar Längen vor der Zone aus, damit du weit darauf zuhalten kannst. Ein später Sinneswechsel bedeutet eine enge Kurve und einen weiten Ausgang.', 'Kapı şamandırasını bölgeden epey önce seç ki ona doğru geniş açılabilesin. Geç değiştirilen fikir, dar bir dönüş ve geniş çıkış demektir.', 'Choisis ta bouée de porte bien quelques longueurs avant la zone, pour pouvoir arriver large. Changer d’avis au dernier moment, c’est un virage serré et une sortie large.') },
      { id: 'wide', fig: 'wide', h: t('Wide in, tight out', 'Широко зайти — узко выйти', 'Abierto al entrar, cerrado al salir', 'Weit hinein, eng hinaus', 'Geniş gir, dar çık', 'Large en entrée, serré en sortie'), p: [
        t('Approach a leeward mark a little wide and turn so that you leave it close, already close-hauled. A boat that cuts in tight comes out wide and below the boats behind her, in their dirty air.',
          'Подходи к нижнему знаку чуть шире и поворачивай так, чтобы выйти от него вплотную, уже в бейдевинд. Лодка, которая срезает внутрь, выходит широко, под лодками позади и в их ветровой тени.', 'Aproxímate a una baliza de sotavento algo abierto y gira de modo que la dejes cerca, ya de ceñida. Un barco que se cierra mucho sale abierto y por debajo de los que vienen detrás, en su aire sucio.', 'Nähere dich einer Leetonne etwas weit und drehe so, dass du sie dicht verlässt, schon hoch am Wind. Ein Boot, das eng einschneidet, kommt weit und unterhalb der Boote hinter ihm heraus, in deren Abwind.', 'Rüzgâraltı şamandırasına biraz geniş yaklaş ve ondan yakın, daha şimdiden orsada ayrılacak şekilde dön. Dar kesen tekne geniş ve arkasındaki teknelerin altında, onların kirli rüzgârında çıkar.', 'Approche une bouée sous le vent un peu au large et tourne de façon à la quitter au ras, déjà au près serré. Un bateau qui coupe au plus court en entrée ressort large et sous le vent des bateaux qui le suivent, dans leur vent perturbé.'),
      ] },
      { id: 'room', h: t('Room in the zone', 'Место в зоне', 'Espacio en la zona', 'Raum in der Zone', 'Bölgede alan', 'La place dans la zone'), p: [
        t('When the first of two overlapped boats reaches the zone, three hull lengths from the mark, the outside boat must give the inside one room to round (rule 18). Get the inside overlap before the zone; an overlap made inside it doesn’t count if you came from clear astern. Between boats on opposite tacks on a beat, at the windward mark, rule 18 doesn’t apply.',
          'Когда первая из двух связанных лодок входит в зону — три корпуса от знака, — внешняя должна дать внутренней место, чтобы обогнуть (правило 18). Установи внутреннюю связанность до зоны: если ты пришёл чисто позади, связанность, установленная внутри зоны, не считается. Между лодками на разных галсах на лавировке, у верхнего знака, правило 18 не действует.', 'Cuando el primero de dos barcos con compromiso llega a la zona, a tres esloras de la baliza, el barco exterior debe dar al interior espacio para redondear (regla 18). Consigue el compromiso interior antes de la zona; un compromiso hecho dentro de ella no cuenta si vienes libre por la popa. Entre barcos en amuras opuestas en una ceñida, en la baliza de barlovento, la regla 18 no se aplica.', 'Wenn das erste von zwei überlappenden Booten die Zone erreicht, drei Rumpflängen von der Bahnmarke, muss das äußere Boot dem inneren Raum zum Runden geben (Regel 18). Hole dir die innere Überlappung vor der Zone; eine Überlappung, die du innerhalb herstellst, zählt nicht, wenn du von klar achteraus kamst. Zwischen Booten auf entgegengesetzten Bugen am Wind gilt an der Luvtonne Regel 18 nicht.', 'Bindirmeli iki teknenin ilki bölgeye, yani şamandıradan üç tekne boyuna ulaştığında, dıştaki tekne içtekine şamandırayı dönmesi için alan vermelidir (kural 18). İç bindirmeyi bölgeden önce kur; açık arkadan gelirsen bölgenin içinde kurulan bindirme sayılmaz. Orsa ayağında zıt kontradaki tekneler arasında, rüzgârüstü şamandırasında, kural 18 geçerli değildir.', 'Quand le premier de deux bateaux engagés atteint la zone, à trois longueurs de coque de la bouée, le bateau à l’extérieur doit donner au bateau à l’intérieur la place de passer (règle 18). Prends l’engagement intérieur avant la zone : un engagement établi à l’intérieur ne compte pas si tu arrivais en route libre derrière. Entre bateaux sur des bords opposés au près, à la bouée au vent, la règle 18 ne s’applique pas.'),
        t('Touch a mark and you take a penalty turn (rule 31) — in the game, one turn through a tack and a gybe.',
          'Коснулся знака — делай штрафной оборот (правило 31); в игре это один оборот через оверштаг и фордевинд.', 'Toca una baliza y haces un giro de penalización (regla 31): en el juego, un giro con una virada y una trasluchada.', 'Berührst du eine Bahnmarke, nimmst du einen Strafkringel (Regel 31) – im Spiel eine Drehung durch eine Wende und eine Halse.', 'Şamandıraya dokunursan ceza dönüşü yaparsın (kural 31); oyunda bu, bir tramola ve bir kavançadan oluşan tek dönüştür.', 'Touche une bouée et tu fais un tour de pénalité (règle 31) — dans le jeu, un tour avec un virement de bord et un empannage.'),
      ], tip: t('Outside at a leeward mark? Rather than sail round her, slow down, drop in behind her and round tight: you come out to windward of her, in clear air.',
        'Снаружи у нижнего знака? Вместо того чтобы обходить её снаружи, притормози, зайди ей за корму и обогни вплотную: выйдешь на ветер от неё, в чистый ветер.', '¿Por fuera en una baliza de sotavento? En vez de rodearlo, frena, métete detrás y redondea cerrado: sales a barlovento de él, con aire limpio.', 'Außen an einer Leetonne? Statt um das Innenboot herumzusegeln, werde langsamer, lass dich hinter es fallen und runde eng: Du kommst luvwärts von ihm heraus, in freiem Wind.', 'Rüzgâraltı şamandırasında dışarıda mısın? Onun çevresinden dolaşmak yerine yavaşla, arkasına düş ve dar dön: rüzgârüstüne, temiz rüzgâra çıkarsın.', 'À l’extérieur à une bouée sous le vent ? Plutôt que de faire le tour par l’extérieur, ralentis, glisse-toi derrière lui et passe au ras : tu ressors au vent de lui, dans un vent propre.') },
    ],
    more: [
      { label: t('Room at marks, rule by rule', 'Место у знаков, правило за правилом', 'Espacio en las balizas, regla a regla', 'Raum an Bahnmarken, Regel für Regel', 'Şamandıralarda alan, kural kural', 'La place aux bouées, règle par règle'), href: rr(lang, 'marks') },
      { label: t('Glossary: zone, mark-room, layline', 'Словарь: зона, место у знака, лейлайн', 'Glosario: zona, espacio en baliza, layline', 'Glossar: Zone, Bahnmarkenraum, Layline', 'Sözlük: bölge, şamandıra alanı, layline', 'Glossaire : zone, place à la marque, lay-line'), href: '/learn/glossary#zone' },
    ],
    try: { label: t('Sail today’s race', 'Пройди гонку дня', 'Navega la regata del día', 'Die Regatta des Tages segeln', 'Günün yarışına çık', 'Cours la régate du jour'), href: '/race', text: t(
      'A windward mark, a gate, five boats arriving with you and the rules on the water.',
      'Верхний знак, ворота, пять лодок, которые приходят вместе с тобой, и правила на воде.', 'Una baliza de barlovento, una puerta, cinco barcos llegando contigo y las reglas en el agua.', 'Eine Luvtonne, ein Tor, fünf Boote, die mit dir ankommen, und die Regeln auf dem Wasser.', 'Bir rüzgârüstü şamandırası, bir kapı, seninle birlikte varan beş tekne ve suyun üzerindeki kurallar.', 'Une bouée au vent, une porte, cinq bateaux qui arrivent avec toi et les règles sur l’eau.') },
  };

  if (slug === 'downwind') return {
    slug,
    title: t('Sailing downwind: the gennaker, angles and gybes', 'Попутные курсы: генакер, углы и повороты', 'Navegar de popa: el gennaker, los ángulos y las trasluchadas', 'Vor dem Wind segeln: der Gennaker, Winkel und Halsen', 'Pupada yelken açmak: gennaker, açılar ve kavançalar', 'Naviguer au portant : le gennaker, les angles et les empannages'),
    short: t('Sailing downwind', 'Попутные курсы', 'Navegar de popa', 'Vor dem Wind segeln', 'Pupada yelken açmak', 'Naviguer au portant'),
    kicker: t('Racing guides · downwind', 'Пособия по гонкам · попутный', 'Guías de regata · de popa', 'Regattaleitfäden · vor dem Wind', 'Yarış rehberleri · pupa', 'Guides de régate · portant'),
    img: shot('gd-downwind-v2', t('Your boat on the run in the game under her gennaker, another yacht alongside under hers', 'Твоя лодка на попутном курсе в игре под генакером, рядом другая яхта под своим', 'Tu barco en la empopada en el juego bajo su gennaker, con otro yate al lado bajo el suyo', 'Dein Boot auf dem Vorwindkurs im Spiel unter Gennaker, daneben eine andere Yacht unter ihrem', 'Oyunda pupada gennakeri açık teknen, yanında kendi gennakeriyle bir başka yat', 'Ton bateau au portant dans le jeu sous gennaker, un autre yacht à côté sous le sien'), 3840, 1600),
    description: t(
      'How to sail fast downwind in a race: when to set the gennaker, sailing angles instead of dead downwind, gybing on the lifts, avoiding a crash gybe or a death roll, and surfing waves.',
      'Как быстро идти на попутных курсах в гонке: когда ставить генакер, углы вместо чистого фордевинда, фордевинд на отходе, как избежать самопроизвольного поворота и брочинга, сёрфинг на волне.', 'Cómo navegar rápido de popa en una regata: cuándo izar el gennaker, navegar por ángulos en vez de en popa cerrada, trasluchar con las roladas favorables, evitar una trasluchada violenta o un vuelco por popa, y surfear olas.', 'So segelst du in einer Regatta schnell vor dem Wind: wann du den Gennaker setzt, Segelwinkel statt genau vor dem Wind, Halsen auf den Raumern, eine Patenthalse oder einen Death Roll vermeiden und auf Wellen surfen.', 'Bir yarışta pupada nasıl hızlı gidilir: gennaker ne zaman açılır, tam pupa yerine açılarla yelken açmak, lehte dönüşlerde kavança atmak, kaza kavançasından ve ölüm yuvarlanmasından kaçınmak ve dalgalarda sörf yapmak.', 'Comment aller vite au portant en régate : quand envoyer le gennaker, naviguer aux angles plutôt qu’en plein vent arrière, empanner sur les adonnantes, éviter un empannage involontaire ou un départ au lof, et surfer les vagues.'),
    intro: t(
      'Downwind looks like the easy part: the wind is behind you and the boat feels slower than it is. But the gaps between boats open and close fastest here, with the big sail up, the shifts and the waves.',
      'Попутный курс кажется лёгким: ветер сзади, и лодка будто идёт медленнее, чем на самом деле. Но именно здесь, с большим парусом, сдвигами ветра и волной, разрывы между лодками растут и тают быстрее всего.', 'La popa parece la parte fácil: el viento viene por detrás y el barco parece más lento de lo que es. Pero las distancias entre barcos se abren y se cierran más rápido aquí, con la vela grande izada, las roladas y las olas.', 'Der Kurs vor dem Wind sieht nach dem leichten Teil aus: Der Wind kommt von hinten, und das Boot fühlt sich langsamer an, als es ist. Doch hier öffnen und schließen sich die Abstände zwischen den Booten am schnellsten, mit dem großen Segel oben, den Winddrehern und den Wellen.', 'Pupa kolay kısım gibi görünür: rüzgâr arkandadır ve tekne olduğundan yavaş hisseder. Ama tekneler arasındaki açıklar en hızlı burada açılır ve kapanır; büyük yelken açıkken, rüzgâr dönüşleri ve dalgalarla.', 'Le portant a l’air de la partie facile : le vent est derrière toi et le bateau semble plus lent qu’il ne l’est. Mais c’est là que les écarts entre bateaux s’ouvrent et se referment le plus vite, avec la grande voile envoyée, les bascules et les vagues.'),
    sections: [
      { id: 'kite', h: t('Set the gennaker', 'Ставь генакер', 'Iza el gennaker', 'Setze den Gennaker', 'Gennakeri aç', 'Envoie le gennaker'), p: [
        t('The gennaker is a big, light sail set from the bow, and it is most of a boat’s speed downwind. Set it once you have borne away round the windward mark and are clear of other boats; hoisting and dropping take the crew a few seconds. In light air on a reach, a flatter code zero does the same job closer to the wind.',
          'Генакер — большой лёгкий парус, который ставят с носа, и на попутных курсах он даёт лодке большую часть скорости. Ставь его, когда увалился за верхним знаком и отошёл от других лодок; постановка и уборка занимают у команды несколько секунд. В слабый ветер на галфвинде ту же работу ближе к ветру делает более плоский код-зеро.', 'El gennaker es una vela grande y ligera que se iza desde la proa, y es la mayor parte de la velocidad de un barco de popa. Ízalo cuando hayas arribado tras la baliza de barlovento y estés libre de otros barcos; izar y arriar le lleva unos segundos a la tripulación. Con poco viento en un través, un código cero más plano hace el mismo trabajo más cerca del viento.', 'Der Gennaker ist ein großes, leichtes Segel, das am Bug gesetzt wird, und er macht den größten Teil der Geschwindigkeit eines Bootes vor dem Wind aus. Setze ihn, sobald du um die Luvtonne abgefallen und frei von anderen Booten bist; Setzen und Bergen dauern für die Crew ein paar Sekunden. Bei leichtem Wind auf Raumschotskurs leistet ein flacherer Code Zero dasselbe näher am Wind.', 'Gennaker pruvadan açılan büyük, hafif bir yelkendir ve bir teknenin pupadaki hızının çoğunu o sağlar. Rüzgârüstü şamandırasını boşlayarak döndükten ve diğer teknelerden açık kaldıktan sonra aç; çekmek ve indirmek mürettebatın birkaç saniyesini alır. Apazda hafif havada daha yassı bir code zero, rüzgâra daha yakın aynı işi görür.', 'Le gennaker est une grande voile légère envoyée depuis l’étrave, et il fait l’essentiel de la vitesse d’un bateau au portant. Envoie-le une fois abattu après la bouée au vent et dégagé des autres bateaux ; l’envoyer et l’affaler prend quelques secondes à l’équipage. Dans le petit temps au largue, un code zéro plus plat fait le même travail plus près du vent.'),
      ], tip: t('In the game the gennaker takes some 15 seconds to set in a medium breeze, longer in a strong one, and the hoist is abandoned if you come up above a beam reach before it’s set: bear away first, then press Kite.',
        'В игре генакер ставят секунд 15 в средний ветер и дольше в сильный, а если до конца постановки привестись круче галфвинда, постановку бросают: сначала увались, потом жми «Генакер».', 'En el juego el gennaker tarda unos 15 segundos en izarse con brisa media, más con brisa fuerte, y la izada se aborta si orzas por encima de un través antes de que esté izado: arriba primero, y luego pulsa Kite.', 'Im Spiel braucht der Gennaker bei mittlerem Wind etwa 15 Sekunden zum Setzen, bei starkem länger, und das Setzen wird abgebrochen, wenn du höher als einen Halbwindkurs anluvst, bevor er oben ist: Falle zuerst ab, dann drücke Kite.', 'Oyunda gennaker orta şiddette rüzgârda yaklaşık 15 saniyede açılır, güçlü rüzgârda daha uzun sürer; açılmadan önce yan apazdan daha yukarı çıkarsan çekme işlemi iptal edilir: önce boşla, sonra Gennaker’a bas.', 'Dans le jeu, le gennaker met environ 15 secondes à s’établir dans une brise moyenne, plus dans une brise forte, et l’envoi est abandonné si tu remontes au-dessus du travers avant qu’il soit établi : abats d’abord, puis appuie sur Kite.') },
      { id: 'angles', h: t('Sail angles, not dead downwind', 'Иди углами, а не чистым фордевиндом', 'Ángulos, no popa cerrada', 'Segelwinkel, nicht genau vor dem Wind', 'Tam pupa değil, açılarla yelken aç', 'Des angles, pas le plein vent arrière'), p: [
        t('With an asymmetric gennaker most boats are faster with the wind a little off the stern than dead behind, so they reach down the run in a couple of gybes rather than straight at the mark. Head up a few degrees in a lull to keep the speed up, and bear away in a gust, when the boat can go deeper at the same speed.',
          'С асимметричным генакером большинство лодок идут быстрее, когда ветер чуть сбоку от кормы, чем строго сзади, поэтому проходят попутный в бакштаг с парой поворотов, а не прямо на знак. В затишье приведись на несколько градусов, чтобы не терять скорость, а в порыве увались — лодка пойдёт глубже с той же скоростью.', 'Con un gennaker asimétrico la mayoría de los barcos van más rápido con el viento algo abierto por la popa que justo detrás, así que bajan la empopada en un par de trasluchadas en vez de ir directos a la baliza. Orza unos grados en una calma para mantener la velocidad, y arriba en una racha, cuando el barco puede ir más bajo a la misma velocidad.', 'Mit einem asymmetrischen Gennaker sind die meisten Boote mit dem Wind leicht von achtern schneller als genau von hinten, deshalb legen sie den Vorwindkurs in ein paar Halsen zurück, statt direkt auf die Bahnmarke zuzuhalten. Luve in einer Flaute ein paar Grad an, um die Fahrt zu halten, und falle in einer Bö ab, wenn das Boot bei gleicher Fahrt tiefer gehen kann.', 'Asimetrik gennakerle çoğu tekne rüzgâr tam arkadan gelmek yerine biraz kıç omuzluktan gelince daha hızlıdır; bu yüzden pupa ayağını doğrudan şamandıraya gitmek yerine birkaç kavançayla iner. Rüzgâr kesilince hızı korumak için birkaç derece orsala, hamlede ise tekne aynı hızla daha derine gidebildiği için boşla.', 'Avec un gennaker asymétrique, la plupart des bateaux vont plus vite avec le vent un peu décalé de l’arrière que plein arrière : ils descendent le bord de portant en deux empannages plutôt que droit sur la bouée. Lofe de quelques degrés dans une molle pour garder la vitesse, et abats dans une risée, quand le bateau peut descendre plus bas à la même vitesse.'),
      ], tip: t('Steer by the speed: head up until she picks up, then bear away as far as you can without losing it. Where she starts to slow is your angle.',
        'Рули по скорости: приводись, пока лодка не разгонится, потом уваливайся настолько, насколько можно без потери скорости. Где она начинает замедляться — там и твой угол.', 'Gobierna por la velocidad: orza hasta que acelere, luego arriba todo lo que puedas sin perderla. Donde empieza a frenar está tu ángulo.', 'Steuere nach der Fahrt: Luve an, bis sie anzieht, dann falle so weit ab, wie du kannst, ohne sie zu verlieren. Wo sie langsamer wird, liegt dein Winkel.', 'Hıza göre dümen kır: tekne hız alana kadar orsala, sonra hızı kaybetmeden gidebildiğin kadar boşla. Yavaşlamaya başladığı yer senin açındır.', 'Barre à la vitesse : lofe jusqu’à ce qu’il accélère, puis abats autant que possible sans la perdre. Là où il commence à ralentir, c’est ton angle.') },
      { id: 'gybe', h: t('Gybe on the lifts', 'Фордевинд на отходе', 'Trasluca con las roladas favorables', 'Halse auf den Raumern', 'Lehte dönüşlerde kavança at', 'Empanne sur les adonnantes'), p: [
        t('Downwind the shifts work the other way round from the beat: a lift makes you head up, away from the mark, to keep your angle to the wind. Gybe, and the same shift points you at the mark again.',
          'На попутном сдвиги работают наоборот по сравнению с лавировкой: отход заставляет приводиться, уходя от знака, чтобы сохранить угол к ветру. Сделай поворот фордевинд — и тот же сдвиг снова поведёт тебя к знаку.', 'De popa las roladas funcionan al revés que en la ceñida: una rolada favorable te hace orzar, alejándote de la baliza, para mantener tu ángulo con el viento. Trasluca, y la misma rolada te apunta de nuevo a la baliza.', 'Vor dem Wind wirken die Dreher umgekehrt wie am Wind: Ein Raumer lässt dich anluven, weg von der Bahnmarke, um deinen Winkel zum Wind zu halten. Halse, und derselbe Dreher zeigt wieder auf die Bahnmarke.', 'Pupada rüzgâr dönüşleri orsadakinin tersi çalışır: lehte bir dönüş, rüzgâra karşı açını korumak için seni şamandıradan uzağa, orsaya doğru götürür. Kavança at, aynı dönüş seni yeniden şamandıraya doğru yöneltir.', 'Au portant, les bascules jouent à l’inverse du près : une adonnante te fait lofer, loin de la bouée, pour garder ton angle au vent. Empanne, et la même bascule te remet le cap sur la bouée.'),
      ], tip: t('Gybe at full speed, best running down a wave: in a strong breeze a slow gybe is the one that wraps the gennaker round the forestay — in the game too.',
        'Делай фордевинд на полной скорости, лучше всего скатываясь с волны: в сильный ветер именно на медленном повороте генакер заматывается вокруг штага — и в игре тоже.', 'Trasluca a toda velocidad, mejor bajando por una ola: con brisa fuerte, una trasluchada lenta es la que enrolla el gennaker en el estay, también en el juego.', 'Halse mit voller Fahrt, am besten eine Welle hinab: Bei starkem Wind ist eine langsame Halse die, bei der sich der Gennaker um das Vorstag wickelt – im Spiel auch.', 'Kavançayı tam hızda at, en iyisi bir dalganın yüzünden inerken: güçlü rüzgârda yavaş bir kavança gennakeri baş istaya dolayan kavançadır; oyunda da öyle.', 'Empanne à pleine vitesse, idéalement en descendant une vague : dans la brise forte, c’est l’empannage lent qui enroule le gennaker autour de l’étai — dans le jeu aussi.') },
      { id: 'lee', h: t('Not too far by the lee', 'Не уваливайся дальше фордевинда', 'No demasiado por la contra', 'Nicht zu weit „by the lee“', 'Rüzgârın tersine fazla gitme', 'Pas trop sur la panne'), p: [
        t('Bear away past dead downwind and the wind gets behind the mainsail: you are sailing by the lee. Go too far and the boom slams across on its own, a crash gybe; with the gennaker up she can roll and round up, a death roll. When the game warns you that you are by the lee, gybe or head up.',
          'Увалишься дальше чистого фордевинда — ветер зайдёт за грот с другой стороны. Если уйти слишком далеко, гик перебросит сам — самопроизвольный поворот; с генакером лодку может положить и привести — брочинг. Когда игра предупреждает, что ты увалился дальше фордевинда, делай поворот фордевинд или приводись.', 'Si arribas más allá de la popa total, el viento se mete por detrás de la mayor: navegas por la contra. Si te pasas, la botavara cruza de golpe sola, una trasluchada violenta; con el gennaker izado puede escorar y orzar, un vuelco por popa. Cuando el juego te avise de que vas por la contra, trasluca u orza.', 'Falle über den Vorwindkurs hinaus ab, und der Wind kommt hinter das Großsegel: Du segelst „by the lee“. Geh zu weit, und der Baum schlägt von allein hinüber, eine Patenthalse; mit gesetztem Gennaker kann sich das Boot hinlegen und in den Wind schießen, ein Death Roll. Warnt dich das Spiel, dass du by the lee segelst, halse oder luve an.', 'Tam pupanın ötesine boşlarsan rüzgâr ana yelkenin arkasına geçer: rüzgârın tersinde, “by the lee” yelken açıyorsun. Çok ileri gidersen bom kendi kendine savrulur, kaza kavançası olur; gennaker açıkken tekne yatıp orsalayabilir, ölüm yuvarlanması olur. Oyun sana rüzgârın tersinde olduğunu bildirince kavança at ya da orsala.', 'Abats au-delà du vent arrière et le vent passe derrière la grand-voile : tu navigues sur la panne. Va trop loin et la bôme passe d’elle-même, c’est l’empannage involontaire ; gennaker envoyé, le bateau peut rouler et partir au lof, c’est le « death roll ». Quand le jeu t’avertit que tu es sur la panne, empanne ou lofe.'),
      ], tip: t('The stronger the wind and the bigger the waves, the less by the lee she will take before the boom comes across on its own. In a blow, gybe or head up as soon as the warning shows.',
        'Чем сильнее ветер и выше волна, тем меньше можно уваливаться дальше фордевинда, прежде чем гик перебросит сам. В сильный ветер делай поворот фордевинд или приводись, как только появилось предупреждение.', 'Cuanto más fuerte el viento y más grandes las olas, menos por la contra aguantará antes de que la botavara cruce sola. Con viento duro, trasluca u orza en cuanto salga el aviso.', 'Je stärker der Wind und je größer die Wellen, desto weniger by the lee verträgt sie, bevor der Baum von allein überkommt. Halse oder luve bei Starkwind an, sobald die Warnung erscheint.', 'Rüzgâr ne kadar güçlü ve dalga ne kadar büyükse, tekne bom kendiliğinden geçmeden önce o kadar az rüzgârın tersine gidebilir. Sert havada uyarı çıkar çıkmaz kavança at ya da orsala.', 'Plus le vent est fort et les vagues grosses, moins le bateau accepte d’être sur la panne avant que la bôme passe d’elle-même. Dans la brise, empanne ou lofe dès que l’avertissement s’affiche.') },
      { id: 'waves', h: t('Surf the waves', 'Лови волну', 'Surfea las olas', 'Surfe auf den Wellen', 'Dalgalarda sörf yap', 'Surfe les vagues'), p: [
        t('In a strong breeze the waves can carry the boat faster than the wind alone. Luff up a little as a wave lifts the stern to catch it, then bear away down its face and ride it as long as you can.',
          'В сильный ветер волна может нести лодку быстрее, чем один ветер. Когда волна поднимает корму, чуть приведись, чтобы поймать её, затем увались вниз по склону и держись на ней сколько получится.', 'Con brisa fuerte las olas pueden llevar al barco más rápido que el viento solo. Orza un poco cuando una ola levanta la popa para engancharla, luego arriba por su cara y móntala mientras puedas.', 'Bei starkem Wind können die Wellen das Boot schneller tragen als der Wind allein. Luve ein wenig an, wenn eine Welle das Heck anhebt, um sie zu fangen, falle dann an ihrer Vorderseite ab und reite sie, so lange du kannst.', 'Güçlü rüzgârda dalgalar tekneyi yalnızca rüzgârın verebileceğinden daha hızlı taşıyabilir. Bir dalga kıçı kaldırırken ona tutunmak için biraz orsala, sonra yüzünden aşağı boşla ve onu olabildiğince uzun süre sür.', 'Dans la brise forte, les vagues peuvent porter le bateau plus vite que le vent seul. Lofe un peu quand une vague soulève l’arrière pour l’attraper, puis abats dans sa pente et surfe-la le plus longtemps possible.'),
      ], tip: t('In the game the waves carry you only in more than about 13 knots, with the wind well aft of the beam; Surfing! shows while one does.',
        'В игре волна несёт лодку только при ветре сильнее 13 узлов, когда он дует заметно сзади траверза; пока несёт, на экране «Сёрфинг!».', 'En el juego las olas te llevan solo con más de unos 13 nudos, con el viento bien por detrás del través; ¡Surfing! aparece mientras lo haces.', 'Im Spiel tragen dich die Wellen nur bei mehr als etwa 13 Knoten und mit dem Wind weit achterlich von querab; Surfing! erscheint, solange eine dich trägt.', 'Oyunda dalgalar seni yalnızca yaklaşık 13 knotun üzerinde ve rüzgâr apazın çok gerisindeyken taşır; biri taşırken Surfing! görünür.', 'Dans le jeu, les vagues ne te portent qu’au-delà d’environ 13 nœuds, le vent bien en arrière du travers ; Surf ! s’affiche pendant que l’une d’elles te porte.') },
    ],
    more: [
      { label: t('Headers and lifts', 'Заходы и отходы ветра', 'Roladas desfavorables y favorables', 'Dreher und Raumer', 'Aleyhte ve lehte dönüşler', 'Refus et adonnantes'), href: '/learn/shifts#down' },
      { label: t('FAQ: crash gybe and death roll', 'Вопросы и ответы: самопроизвольный поворот и брочинг', 'FAQ: trasluchada violenta y vuelco por popa', 'FAQ: Patenthalse und Death Roll', 'SSS: kaza kavançası ve ölüm yuvarlanması', 'FAQ : empannage involontaire et death roll'), href: '/faq' },
    ],
    try: { label: t('Race in a strong breeze', 'Гонка в сильный ветер', 'Regata con brisa fuerte', 'Regatta bei Starkwind', 'Güçlü rüzgârda yarış', 'Régater dans la brise'), href: '/race/free', text: t(
      'Set a strong breeze in a custom race: the gennaker, the waves to surf and a boom that bites back.',
      'Поставь сильный ветер в своей гонке: генакер, волна для сёрфинга и гик, который может ударить.', 'Pon brisa fuerte en una regata personalizada: el gennaker, las olas para surfear y una botavara que muerde.', 'Stelle in einer freien Regatta Starkwind ein: der Gennaker, die Wellen zum Surfen und ein Baum, der zurückbeißt.', 'Serbest bir yarışta güçlü rüzgâr ayarla: gennaker, sörf yapılacak dalgalar ve geri tepen bir bom.', 'Choisis une brise forte dans une régate libre : le gennaker, les vagues à surfer et une bôme qui ne pardonne pas.') },
  };

  if (slug === 'trim') return {
    slug,
    title: t('Sail trim and boat speed', 'Настройка парусов и скорость лодки', 'Trimado y velocidad del barco', 'Segeltrimm und Bootsgeschwindigkeit', 'Yelken trimi ve tekne hızı', 'Réglage des voiles et vitesse'),
    short: t('Sail trim and speed', 'Настройка и скорость', 'Trimado y velocidad', 'Segeltrimm und Geschwindigkeit', 'Yelken trimi ve hız', 'Réglage des voiles et vitesse'),
    kicker: t('Racing guides · speed', 'Пособия по гонкам · скорость', 'Guías de regata · velocidad', 'Regattaleitfäden · Geschwindigkeit', 'Yarış rehberleri · hız', 'Guides de régate · vitesse'),
    img: shot('gd-trim-v2', t('Your boat sailing upwind in the game, her main and jib trimmed in', 'Твоя лодка идёт в лавировку в игре, грот и стаксель выбраны', 'Tu barco navegando de ceñida en el juego, con la mayor y el foque trimados', 'Dein Boot am Wind im Spiel, Groß und Fock dicht gesetzt', 'Oyunda orsa yelken açan teknen, ana yelkeni ve flokü trim edilmiş', 'Ton bateau au près dans le jeu, grand-voile et foc bordés'), 3840, 1600),
    description: t(
      'How to make a sailboat go fast: trimming the main and jib, steering smoothly, footing for speed upwind, controlling heel, and reefing or changing jibs in a blow.',
      'Как заставить парусную лодку идти быстро: настройка грота и стакселя, плавное рулевое управление, увалиться ради скорости на лавировке, контроль крена, риф и смена стакселя в сильный ветер.', 'Cómo hacer que un velero vaya rápido: trimar la mayor y el foque, gobernar con suavidad, abrir rumbo para ganar velocidad de ceñida, controlar la escora y rizar o cambiar de foque con viento duro.', 'So wird ein Segelboot schnell: Groß und Fock trimmen, weich steuern, für Fahrt abfallen am Wind, die Krängung kontrollieren und bei Starkwind reffen oder die Fock wechseln.', 'Bir yelkenli nasıl hızlı gider: ana yelken ve floku trim etmek, yumuşak dümen kırmak, orsada hız için boşlamak, yatışı denetlemek ve sert havada camadan almak ya da flok değiştirmek.', 'Comment faire aller vite un voilier : régler la grand-voile et le foc, barrer en douceur, abattre pour la vitesse au près, contrôler la gîte, et prendre un ris ou changer de foc dans la brise.'),
    intro: t(
      'Tactics win races only if the boat is fast enough to use them. Most lost speed comes from three things: sails set wrong for the wind, too much rudder, and too much heel.',
      'Тактика выигрывает гонки, только если лодке хватает скорости ею воспользоваться. Большая часть потерянной скорости — от трёх вещей: паруса не по ветру, слишком много руля и слишком большой крен.', 'La táctica gana regatas solo si el barco es lo bastante rápido para aprovecharla. La mayor parte de la velocidad perdida viene de tres cosas: velas mal reguladas para el viento, demasiado timón y demasiada escora.', 'Taktik gewinnt Regatten nur, wenn das Boot schnell genug ist, sie zu nutzen. Der größte Teil des Geschwindigkeitsverlusts hat drei Ursachen: falsch gesetzte Segel für den Wind, zu viel Ruder und zu viel Krängung.', 'Taktik, ancak tekne onu kullanacak kadar hızlıysa yarış kazandırır. Kaybedilen hızın çoğu üç şeyden gelir: rüzgâra göre yanlış ayarlanmış yelkenler, fazla dümen ve fazla yatış.', 'La tactique ne gagne des régates que si le bateau va assez vite pour en profiter. L’essentiel de la vitesse perdue vient de trois choses : des voiles mal réglées pour le vent, trop de barre et trop de gîte.'),
    sections: [
      { id: 'sheet', h: t('Set the sheet for the wind', 'Шкот — по ветру', 'Regula la escota según el viento', 'Stelle die Schot auf den Wind ein', 'İskotayı rüzgâra göre ayarla', 'Règle l’écoute sur le vent'), p: [
        t('A sail works when the wind flows smoothly along both sides of it. Let it out too far and its front edge flaps; pull it in too far and the flow breaks away behind it and the boat slows without showing it. Every time you change course, the sheets have to follow.',
          'Парус работает, когда ветер плавно обтекает его с обеих сторон. Перетравишь — передняя кромка заполощет; перебрал — поток срывается с подветренной стороны, и лодка замедляется незаметно. При каждой смене курса шкоты должны следовать за ним.', 'Una vela funciona cuando el viento fluye suave por los dos lados. Si la sueltas demasiado, el borde de ataque flamea; si la cazas demasiado, el flujo se desprende por detrás y el barco frena sin que lo parezca. Cada vez que cambias de rumbo, las escotas tienen que acompañar.', 'Ein Segel arbeitet, wenn der Wind glatt an beiden Seiten entlangströmt. Fierst du zu weit, flattert die Vorderkante; holst du zu weit dicht, reißt die Strömung dahinter ab, und das Boot wird langsamer, ohne es zu zeigen. Jedes Mal, wenn du den Kurs änderst, müssen die Schoten folgen.', 'Rüzgâr yelkenin iki yüzünde de düzgün aktığında yelken iş görür. Fazla boşaltırsan ön kenarı çırpınır; fazla çekersen akış arkasında kopar ve tekne belli etmeden yavaşlar. Rotanı her değiştirişinde iskotalar da ona uymalıdır.', 'Une voile travaille quand le vent s’écoule bien des deux côtés. Choque-la trop et son bord d’attaque faseye ; borde-la trop et l’écoulement décroche derrière elle, et le bateau ralentit sans que rien ne se voie. Chaque fois que tu changes de cap, les écoutes doivent suivre.'),
        t('In Up and down each sheet has a green band for the wind you’re in: keep the knob in it. Or let the game trim for you and only steer.',
          'В Up and down у каждого шкота есть зелёная полоса для текущего ветра: держи ползунок в ней. Или пусть игра настраивает паруса сама, а ты только рули.', 'En Up and down cada escota tiene una banda verde para el viento en que estás: mantén el pomo dentro. O deja que el juego trime por ti y limítate a gobernar.', 'In Up and down hat jede Schot ein grünes Band für den Wind, in dem du bist: Halte den Knopf darin. Oder lass das Spiel für dich trimmen und steuere nur.', 'Up and down’da her iskotanın bulunduğun rüzgâr için yeşil bir bandı vardır: topuzu içinde tut. Ya da trimi oyuna bırak, sen yalnızca dümen kır.', 'Dans Up and down, chaque écoute a une bande verte pour le vent où tu es : garde le curseur dedans. Ou laisse le jeu régler pour toi et contente-toi de barrer.'),
      ], tip: t('On a real boat the telltales tell you: the windward ones lifting, pull in or bear away; the leeward ones stalling, ease out or head up.',
        'На настоящей лодке подскажут колдунчики: наветренные задираются — выбери шкот или увались; подветренные повисли — потрави или приведись.', 'En un barco real te lo dicen los catavientos: los de barlovento levantándose, caza o arriba; los de sotavento desprendiéndose, lasca u orza.', 'Auf einem echten Boot zeigen dir die Windfäden den Weg: Heben sich die Luvfäden, hole dicht oder falle ab; stallen die Leefäden, fiere oder luve an.', 'Gerçek teknede ipçikler söyler: rüzgârüstündekiler kalkıyorsa çek ya da boşla; rüzgâraltındakiler duruyorsa (stall) boşalt ya da orsala.', 'Sur un vrai bateau, ce sont les penons qui te le disent : ceux au vent qui se lèvent, borde ou abats ; ceux sous le vent qui décrochent, choque ou lofe.') },
      { id: 'steer', h: t('Steer in small moves', 'Рули маленькими движениями', 'Gobierna con movimientos pequeños', 'Steuere in kleinen Bewegungen', 'Küçük hareketlerle dümen kır', 'Barre par petits gestes'), p: [
        t('The rudder is a brake as well as a steering wheel: every movement of it slows the boat. Make small, early corrections rather than big late ones, and let the boat sail.',
          'Руль не только поворачивает, но и тормозит: каждое его движение замедляет лодку. Делай небольшие ранние поправки вместо больших поздних и дай лодке идти.', 'El timón es un freno además de un volante: cada movimiento lo frena. Haz correcciones pequeñas y tempranas en vez de grandes y tardías, y deja que el barco navegue.', 'Das Ruder ist nicht nur ein Steuer, sondern auch eine Bremse: Jede Bewegung bremst das Boot. Mache kleine, frühe Korrekturen statt großer, später Korrekturen, und lass das Boot segeln.', 'Dümen yalnızca bir direksiyon değil, aynı zamanda bir frendir: her hareketi tekneyi yavaşlatır. Büyük ve geç düzeltmeler yerine küçük ve erken düzeltmeler yap ve tekneyi yelken açmaya bırak.', 'Le safran est un frein autant qu’un gouvernail : chaque mouvement de barre ralentit le bateau. Fais de petites corrections tôt plutôt que de grandes en retard, et laisse le bateau naviguer.'),
      ], tip: t('Steer with the sails too: easing the main helps her bear away, pulling it in helps her head up, so the rudder has less to do.',
        'Рули и парусами: потравленный грот помогает уваливаться, выбранный — приводиться, и рулю остаётся меньше работы.', 'Gobierna también con las velas: lascar la mayor ayuda a arribar, cazarla ayuda a orzar, así el timón tiene menos que hacer.', 'Steuere auch mit den Segeln: Das Fieren des Großsegels hilft dem Boot beim Abfallen, das Dichtholen beim Anluven, so hat das Ruder weniger zu tun.', 'Yelkenlerle de dümen kır: ana yelkeni boşaltmak boşlamasına, çekmek orsalamasına yardım eder; böylece dümenin yapacak işi azalır.', 'Barre aussi avec les voiles : choquer la grand-voile aide à abattre, la border aide à lofer, et le safran a moins à faire.') },
      { id: 'foot', h: t('Foot to build speed', 'Увались, чтобы разогнаться', 'Abre rumbo para ganar velocidad', 'Falle für Fahrt ab', 'Hız yapmak için boşla', 'Abats pour prendre de la vitesse'), p: [
        t('Upwind, a slow boat pointing as high as a fast one only slips sideways. After a tack, a bad wave or a lull, bear away a few degrees, let her pick up speed, then come back up.',
          'На лавировке медленная лодка, которая идёт так же круто, как быстрая, только сползает вбок. После поворота, неудачной волны или затишья увались на пару градусов, дай лодке разогнаться и потом снова приведись.', 'De ceñida, un barco lento que apunta tan alto como uno rápido solo se desliza de lado. Tras una virada, una mala ola o una calma, arriba unos grados, deja que acelere y vuelve a subir.', 'Am Wind rutscht ein langsames Boot, das so hoch segelt wie ein schnelles, nur seitwärts. Falle nach einer Wende, einer schlechten Welle oder einer Flaute ein paar Grad ab, lass es Fahrt aufnehmen und komm dann wieder hoch.', 'Orsada yavaş bir tekne, hızlı bir tekne kadar yüksekten gidince yalnızca yana kayar. Bir tramoladan, kötü bir dalgadan ya da rüzgâr kesilmesinden sonra birkaç derece boşla, hız almasına izin ver, sonra tekrar yüksel.', 'Au près, un bateau lent qui serre autant qu’un rapide ne fait que dériver. Après un virement, une mauvaise vague ou une molle, abats de quelques degrés, laisse-le reprendre de la vitesse, puis remonte.'),
      ], tip: t('Foot more in waves and light air, where speed is hardest to keep; point higher in flat water and a good breeze.',
        'В волну и слабый ветер, где скорость держать труднее всего, уваливайся больше; в гладкой воде и хорошем ветре можно идти круче.', 'Abre más rumbo con olas y poco viento, donde la velocidad cuesta más mantenerla; apunta más alto con agua plana y buena brisa.', 'Falle mehr ab bei Wellen und leichtem Wind, wo Fahrt am schwersten zu halten ist; segle höher bei glattem Wasser und gutem Wind.', 'Dalgada ve hafif havada, hızı korumanın en zor olduğu yerde daha çok boşla; düz suda ve iyi rüzgârda daha yüksek git.', 'Abats davantage dans les vagues et le petit temps, où la vitesse est la plus dure à garder ; serre plus le vent sur mer plate et dans une bonne brise.') },
      { id: 'heel', h: t('Keep her upright', 'Держи лодку ровно', 'Mantenlo derecho', 'Halte sie aufrecht', 'Tekneyi dik tut', 'Garde-le à plat'), p: [
        t('A boat heeled too far drags her rudder, slides to leeward and wants to round up into the wind. When a gust lays her over, ease the sheet until she comes back up; the game says so when the heel is too much.',
          'Слишком накренённая лодка тянет руль, сползает под ветер и стремится привестись. Когда порыв кладёт её, потрави шкот, пока она не выпрямится; игра подскажет, если крен слишком большой.', 'Un barco demasiado escorado arrastra el timón, se desliza a sotavento y quiere orzar contra el viento. Cuando una racha lo tumba, lasca la escota hasta que se levante; el juego te avisa cuando la escora es excesiva.', 'Ein zu weit gekrängtes Boot schleift das Ruder, rutscht nach Lee und will in den Wind schießen. Legt eine Bö das Boot über, fiere die Schot, bis es wieder hochkommt; das Spiel sagt es dir, wenn die Krängung zu groß ist.', 'Fazla yatmış tekne dümenini sürükler, rüzgâraltına kayar ve rüzgâra doğru orsalamak ister. Bir hamle onu yatırdığında, tekrar doğrulana kadar iskotayı boşalt; yatış fazla olduğunda oyun bunu söyler.', 'Un bateau trop gîté traîne son safran, glisse sous le vent et veut partir au lof. Quand une risée le couche, choque l’écoute jusqu’à ce qu’il se redresse ; le jeu te le dit quand la gîte est trop forte.'),
      ], tip: t('In a gust, ease the main first and keep the jib in: she comes back upright and keeps driving.',
        'В порыв первым трави грот, а стаксель держи: лодка выпрямится и продолжит тянуть.', 'En una racha, lasca primero la mayor y mantén el foque cazado: se endereza y sigue empujando.', 'In einer Bö fiere zuerst das Groß und lass die Fock dicht: Es kommt wieder aufrecht und behält den Vortrieb.', 'Hamlede önce ana yelkeni boşalt ve floku çekili tut: tekne doğrulur ve gitmeye devam eder.', 'Dans une risée, choque d’abord la grand-voile et garde le foc bordé : le bateau se redresse et continue d’avancer.') },
      { id: 'blow', h: t('Reef and change down in a blow', 'Риф и малый стаксель в сильный ветер', 'Riza y cambia a menos trapo con viento duro', 'Reffe und wechsle bei Starkwind nach unten', 'Sert havada camadan al ve küçült', 'Prends un ris et réduis dans la brise'), p: [
        t('When easing the sheet isn’t enough, make the sails smaller: reef the main, and change to the small jib (the J3). A boat with less sail but upright is faster than one with full sail flat on her side.',
          'Когда травить шкот уже не помогает, уменьшай паруса: бери риф на гроте и ставь малый стаксель (J3). Лодка с меньшими парусами, но ровная идёт быстрее той, что с полными парусами лежит на борту.', 'Cuando lascar la escota no basta, reduce las velas: riza la mayor y cambia al foque pequeño (el J3). Un barco con menos vela pero derecho es más rápido que uno con toda la vela tumbado de costado.', 'Reicht das Fieren der Schot nicht, mache die Segel kleiner: Reffe das Groß und wechsle auf die kleine Fock (die J3). Ein Boot mit weniger Segel, aber aufrecht, ist schneller als eines mit vollem Segel flach auf der Seite.', 'İskotayı boşaltmak yetmediğinde yelkenleri küçült: ana yelkenden camada al ve küçük floka (J3) geç. Daha az yelkenli ama dik duran tekne, tam yelkenle yan yatmış tekneden hızlıdır.', 'Quand choquer l’écoute ne suffit plus, réduis la voilure : prends un ris dans la grand-voile et passe au petit foc (le J3). Un bateau avec moins de toile mais à plat va plus vite qu’un bateau toute toile dessus, couché sur le flanc.'),
      ], tip: t('Reef before you need to. In the game tying a reef in takes the crew about 25 seconds and a jib change half a minute, slow while they last: do it on a long leg, not just before a mark or a tack. A reef pays from about 20 knots.',
        'Бери риф заранее. В игре команда берёт риф около 25 секунд, а меняет стаксель полминуты, и всё это время лодка идёт медленнее: делай это на длинном отрезке, а не перед знаком или поворотом. Риф окупается примерно с 20 узлов.', 'Riza antes de necesitarlo. En el juego dar un rizo lleva a la tripulación unos 25 segundos y cambiar de foque medio minuto, lentos mientras duran: hazlo en un tramo largo, no justo antes de una baliza o una virada. Un rizo compensa desde unos 20 nudos.', 'Reffe, bevor du musst. Im Spiel braucht die Crew etwa 25 Sekunden für ein Reff und eine halbe Minute für einen Fockwechsel, in dieser Zeit ist das Boot langsam: Tu es auf einem langen Schenkel, nicht kurz vor einer Bahnmarke oder Wende. Ein Reff lohnt sich ab etwa 20 Knoten.', 'İhtiyaç olmadan önce camada al. Oyunda bir camada almak mürettebatın yaklaşık 25 saniyesini, flok değiştirmek yarım dakikasını alır ve bu sürede tekne yavaştır: bunu uzun bir ayakta yap, şamandıradan ya da tramoladan hemen önce değil. Camada, yaklaşık 20 knottan itibaren kazandırır.', 'Prends un ris avant d’en avoir besoin. Dans le jeu, prendre un ris occupe l’équipage environ 25 secondes et un changement de foc une demi-minute, lent tant que ça dure : fais-le sur un long bord, pas juste avant une bouée ou un virement. Un ris paie à partir d’environ 20 nœuds.') },
    ],
    more: [
      { label: t('How to play: sails in your hands', 'Как играть: паруса в твоих руках', 'Cómo jugar: las velas en tus manos', 'So spielst du: Segel in deinen Händen', 'Nasıl oynanır: yelkenler senin elinde', 'Comment jouer : les voiles en main'), href: '/help#h-controls' },
      { label: t('Glossary: sheet and trim', 'Словарь: шкот и настройка', 'Glosario: escota y trimar', 'Glossar: Schot und Trimm', 'Sözlük: iskota ve trim', 'Glossaire : écoute et réglage'), href: '/learn/glossary#sheet' },
    ],
    try: { label: t('Set up a custom race', 'Настрой свою гонку', 'Prepara una regata personalizada', 'Richte eine freie Regatta ein', 'Serbest yarış kur', 'Préparer une régate libre'), href: '/race/free', text: t(
      'Turn auto-trim off in Settings, pick a medium breeze and sail on the sheets yourself.',
      'Выключи автонастройку в настройках, выбери средний ветер и работай шкотами сам.', 'Desactiva el trimado automático en Ajustes, elige una brisa media y navega tú con las escotas.', 'Schalte den Auto-Trimm in den Einstellungen aus, wähle mittleren Wind und segle die Schoten selbst.', 'Ayarlar’da otomatik trimi kapat, orta şiddette bir rüzgâr seç ve iskotaları kendin yönet.', 'Désactive le réglage automatique dans les Réglages, choisis une brise moyenne et règle les écoutes toi-même.') },
  };

  if (slug === 'rules') return {
    slug,
    title: t('The racing rules in five minutes', 'Правила парусных гонок за пять минут', 'Las reglas de regata en cinco minutos', 'Die Wettfahrtregeln in fünf Minuten', 'Yarış kuralları beş dakikada', 'Les règles de course en cinq minutes'),
    short: t('The racing rules in five minutes', 'Правила гонок за пять минут', 'Las reglas de regata en cinco minutos', 'Die Wettfahrtregeln in fünf Minuten', 'Yarış kuralları beş dakikada', 'Les règles de course en cinq minutes'),
    kicker: t('Racing guides · rules', 'Пособия по гонкам · правила', 'Guías de regata · reglas', 'Regattaleitfäden · Regeln', 'Yarış rehberleri · kurallar', 'Guides de régate · règles'),
    img: shot('gd-rules-v2', t('Yachts on opposite tacks meeting on the beat in the game', 'Яхты на разных галсах сходятся на лавировке в игре', 'Yates en amuras opuestas encontrándose en la ceñida en el juego', 'Yachten auf entgegengesetzten Bugen begegnen sich am Wind im Spiel', 'Oyunda orsada karşılaşan, zıt kontradaki yatlar', 'Des yachts sur des bords opposés qui se croisent au près dans le jeu'), 3840, 1600),
    description: t(
      'The Racing Rules of Sailing that decide almost every meeting on the water: port and starboard, windward and leeward, clear astern, tacking, room at the mark, and how to take a penalty.',
      'Правила парусных гонок, которые решают почти каждую встречу на воде: левый и правый галс, наветренная и подветренная, чистая позади, поворот, место у знака и как отработать штраф.', 'Las Reglas de Regatas a Vela que deciden casi todos los encuentros en el agua: babor y estribor, barlovento y sotavento, libre por la popa, virar, espacio en la baliza y cómo hacer una penalización.', 'Die Wettfahrtregeln Segeln, die fast jede Begegnung auf dem Wasser entscheiden: Backbord und Steuerbord, Luv und Lee, klar achteraus, Wenden, Raum an der Bahnmarke und wie du eine Strafe nimmst.', 'Suda karşılaşmaların neredeyse hepsine karar veren Yelken Yarış Kuralları: iskele ve sancak, rüzgârüstü ve rüzgâraltı, açık arkada, tramola, şamandırada alan ve ceza nasıl alınır.', 'Les Règles de course à la voile qui décident de presque toutes les rencontres sur l’eau : bâbord et tribord, au vent et sous le vent, route libre derrière, le virement de bord, la place à la marque et comment effectuer une pénalité.'),
    intro: t(
      'The Racing Rules of Sailing run to dozens of pages, but when two boats meet, a handful of them decide who keeps clear. These are the ones from Part 2, “When boats meet”, that the computer boats in Up and down race by — and you with them.',
      'Правила парусных гонок занимают десятки страниц, но когда встречаются две лодки, кто кому уступает, решают несколько правил. Вот они — из части 2, «Когда лодки встречаются»: по ним гоняются компьютерные лодки в Up and down, а вместе с ними и ты.', 'El Reglamento de Regatas a Vela ocupa decenas de páginas, pero cuando dos barcos se encuentran, un puñado de reglas decide quién se mantiene separado. Estas son las de la Parte 2, «Cuando los barcos se encuentran», por las que regatean los barcos del ordenador en Up and down, y tú con ellos.', 'Die Wettfahrtregeln Segeln umfassen Dutzende Seiten, aber wenn zwei Boote sich begegnen, entscheiden eine Handvoll davon, wer sich freihält. Das sind die aus Teil 2, „Wenn Boote sich begegnen“, nach denen die Computerboote in Up and down segeln – und du mit ihnen.', 'Yelken Yarış Kuralları onlarca sayfa tutar, ama iki tekne karşılaştığında kimin uzak duracağına bunlardan bir avuç kural karar verir. Bunlar, Up and down’daki bilgisayar tekneleri ile senin de uyduğun, 2. Bölüm’den, “Tekneler karşılaştığında”dan gelen kurallardır.', 'Les Règles de course à la voile font des dizaines de pages, mais quand deux bateaux se rencontrent, une poignée d’entre elles décide qui doit se maintenir à l’écart. Ce sont celles de la partie 2, « Quand les bateaux se rencontrent », que suivent les bateaux de l’ordinateur dans Up and down — et toi avec eux.'),
    sections: [
      { id: 'r10', h: t('Port keeps clear of starboard (rule 10)', 'Левый галс уступает правому (правило 10)', 'Babor se mantiene separado de estribor (regla 10)', 'Backbord hält sich frei von Steuerbord (Regel 10)', 'İskele, sancaktan uzak durur (kural 10)', 'Bâbord se maintient à l’écart de tribord (règle 10)'), p: [
        t('A boat is on starboard tack when the wind comes over her starboard (right) side, with the boom out to port; on port tack the other way round. When two boats on opposite tacks meet, the port-tack boat keeps clear: she tacks, or ducks behind the other’s stern.',
          'Лодка идёт правым галсом, когда ветер дует ей в правый борт, а гик вынесен влево; левым — наоборот. Когда встречаются лодки на разных галсах, уступает та, что идёт левым: она поворачивает или проходит за кормой другой.', 'Un barco está en amura de estribor cuando el viento entra por su costado de estribor (derecho), con la botavara a babor; en amura de babor, al revés. Cuando dos barcos en amuras opuestas se encuentran, el de babor se mantiene separado: vira, o pasa por detrás de la popa del otro.', 'Ein Boot ist auf Steuerbordbug, wenn der Wind über seine Steuerbordseite (rechts) kommt und der Baum nach Backbord steht; auf Backbordbug umgekehrt. Begegnen sich zwei Boote auf entgegengesetzten Bugen, hält sich das Boot auf Backbordbug frei: Es wendet oder geht hinter dem Heck des anderen durch.', 'Bir tekne, rüzgâr sancak (sağ) yanından gelirken ve bom iskeleye açıkken sancak kontradadır; iskele kontrada bunun tersi geçerlidir. Zıt kontradaki iki tekne karşılaştığında iskele kontradaki tekne uzak durur: tramola atar ya da ötekinin kıçının arkasından geçer.', 'Un bateau est tribord amures quand le vent arrive par son côté tribord (droit), la bôme à bâbord ; bâbord amures, c’est l’inverse. Quand deux bateaux sur des bords opposés se rencontrent, le bateau bâbord amures se maintient à l’écart : il vire, ou passe derrière l’arrière de l’autre.'),
        t('The starboard boat usually makes sure with a hail: “Starboard!” A hail is a warning, not a penalty; keep clear in time and nothing happens.',
          'Лодка правого галса обычно предупреждает окликом: «Правый!» Оклик — не штраф, а предупреждение: уступи вовремя, и ничего не будет.', 'El barco de estribor suele asegurarse con un grito: «¡Estribor!». Un grito es un aviso, no una penalización; mantente separado a tiempo y no pasa nada.', 'Das Steuerbordboot sorgt meist mit einem Ruf für Klarheit: „Steuerbord!“ Ein Ruf ist eine Warnung, keine Strafe; hältst du dich rechtzeitig frei, passiert nichts.', 'Sancaktaki tekne genellikle bir çağrıyla bunu belirtir: “Sancak!” Çağrı bir uyarıdır, ceza değildir; zamanında uzak durursan hiçbir şey olmaz.', 'Le bateau tribord prévient en général d’un appel : « Tribord ! » Un appel est un avertissement, pas une pénalité ; maintiens-toi à l’écart à temps et il ne se passe rien.'),
      ], tip: t('Ducking costs less than it looks: bear away early, aim at her stern and come back up to close-hauled as you pass it. A late tack close in front of her is how fouls happen.',
        'Пройти за кормой дешевле, чем кажется: увались заранее, целься в её корму и, проходя её, снова приведись в бейдевинд. Поздний поворот прямо перед её носом — так и случаются нарушения.', 'Pasar por popa cuesta menos de lo que parece: arriba pronto, apunta a su popa y vuelve a la ceñida al pasarla. Una virada tardía justo delante de él es como se producen las faltas.', 'Hinten durchgehen kostet weniger, als es aussieht: Falle früh ab, ziele auf sein Heck und luve wieder auf hoch am Wind an, wenn du es passierst. Eine späte Wende dicht vor ihm ist, wie es zu Fouls kommt.', 'Arkasından geçmek göründüğünden ucuza gelir: erken boşla, kıçına nişan al ve yanından geçerken yeniden orsaya yüksel. Onun hemen önünde yakından atılan geç bir tramola, ihlaller böyle olur.', 'Passer derrière coûte moins qu’il n’y paraît : abats tôt, vise son arrière et remonte au près serré en le passant. Un virement tardif juste devant lui, c’est comme ça qu’arrivent les fautes.') },
      { id: 'r11', h: t('Windward keeps clear of leeward (rule 11)', 'Наветренная уступает подветренной (правило 11)', 'Barlovento se mantiene separado de sotavento (regla 11)', 'Luv hält sich frei von Lee (Regel 11)', 'Rüzgârüstü, rüzgâraltından uzak durur (kural 11)', 'Au vent se maintient à l’écart de sous le vent (règle 11)'), p: [
        t('On the same tack and overlapped — neither boat clear ahead of the other — the windward boat, the one nearer the wind, keeps clear. The leeward boat may luff, turning towards the wind, and the windward boat has to answer.',
          'На одном галсе, когда лодки связаны — ни одна не чисто впереди, — уступает наветренная, та, что ближе к ветру. Подветренная может приводиться, поворачивая к ветру, и наветренная должна отвечать.', 'En la misma amura y con compromiso, sin que ninguno esté libre por la proa del otro, el barco de barlovento, el más cercano al viento, se mantiene separado. El de sotavento puede orzar, girando hacia el viento, y el de barlovento tiene que responder.', 'Auf demselben Bug und überlappend – keines der Boote klar voraus vom anderen – hält sich das Luvboot, das dem Wind nähere, frei. Das Leeboot darf anluven, also zum Wind drehen, und das Luvboot muss darauf reagieren.', 'Aynı kontrada ve bindirmeliyken, yani iki tekneden hiçbiri ötekinin açık önünde değilken, rüzgârüstü tekne, yani rüzgâra daha yakın olan, uzak durur. Rüzgâraltı tekne orsalayabilir, yani rüzgâra doğru dönebilir ve rüzgârüstü tekne buna cevap vermek zorundadır.', 'Sur le même bord et engagés — aucun des deux en route libre devant l’autre —, le bateau au vent, le plus proche du vent, se maintient à l’écart. Le bateau sous le vent peut lofer, en tournant vers le vent, et le bateau au vent doit répondre.'),
        t('There is a limit: a boat that became overlapped to leeward from clear astern, within two of her hull lengths, must not sail above her proper course while the overlap lasts (rule 17).',
          'Но есть предел: если подветренная стала связанной, будучи до этого чисто позади, ближе двух своих корпусов, она не должна идти выше своего надлежащего курса, пока связанность сохраняется (правило 17).', 'Hay un límite: un barco que se puso en compromiso por sotavento viniendo libre por la popa, a menos de dos esloras, no debe navegar por encima de su rumbo debido mientras dure el compromiso (regla 17).', 'Es gibt eine Grenze: Ein Boot, das von klar achteraus innerhalb von zwei seiner Rumpflängen in Lee überlappend wurde, darf nicht höher als seinen richtigen Kurs segeln, solange die Überlappung besteht (Regel 17).', 'Bir sınır vardır: açık arkadan, tekne boyunun iki katı içinde rüzgâraltında bindirme kuran bir tekne, bindirme sürdüğü sürece uygun rotasının üzerinde yelken açmamalıdır (kural 17).', 'Il y a une limite : un bateau qui s’est engagé sous le vent en venant de route libre derrière, à moins de deux de ses longueurs de coque, ne doit pas naviguer au-dessus de sa route normale tant que l’engagement dure (règle 17).'),
      ], tip: t('To windward, keep far enough away that she can luff without touching you. If she luffs and you can’t keep clear, the foul is yours — unless she turned so fast you had no room to (rule 16).',
        'Будучи наветренной, держись так далеко, чтобы она могла привестись, не задев тебя. Если она привелась, а ты не успел уступить, нарушение твоё — если только она не повернула так резко, что уступить было негде (правило 16).', 'A barlovento, mantén distancia suficiente para que pueda orzar sin tocarte. Si orza y no puedes mantenerte separado, la falta es tuya, salvo que haya girado tan rápido que no tuvieras espacio para hacerlo (regla 16).', 'In Luv halte genug Abstand, dass es anluven kann, ohne dich zu berühren. Luvt es an und du kannst dich nicht freihalten, ist das Foul deins – es sei denn, es hat so schnell gedreht, dass dir kein Raum dafür blieb (Regel 16).', 'Rüzgârüstünde, onun sana dokunmadan orsalayabileceği kadar uzakta kal. O orsalarsa ve sen uzak duramazsan ihlal senindir; o sana alan bırakmayacak kadar hızlı dönmüşse hariç (kural 16).', 'Au vent, reste assez loin pour qu’il puisse lofer sans te toucher. S’il lofe et que tu ne peux pas te maintenir à l’écart, la faute est pour toi — sauf s’il a tourné si vite que tu n’avais pas la place de le faire (règle 16).') },
      { id: 'r12', h: t('Clear astern keeps clear of clear ahead (rule 12)', 'Чисто позади уступает чисто впереди (правило 12)', 'Libre por la popa se mantiene separado de libre por la proa (regla 12)', 'Klar achteraus hält sich frei von klar voraus (Regel 12)', 'Açık arkada olan, açık önde olandan uzak durur (kural 12)', 'Route libre derrière se maintient à l’écart de route libre devant (règle 12)'), p: [
        t('On the same tack and not overlapped, the boat behind keeps clear of the boat ahead. Catch up to windward and you are the windward boat; to leeward, and the boat ahead now keeps clear of you — mind rule 17 above.',
          'На одном галсе и без связанности лодка позади уступает лодке впереди. Догнала с наветра — стала наветренной; с подветра — теперь уступает тебе передняя, но помни о правиле 17.', 'En la misma amura y sin compromiso, el barco de detrás se mantiene separado del de delante. Si alcanzas por barlovento, eres el barco de barlovento; por sotavento, y ahora el de delante se mantiene separado de ti: ojo con la regla 17 de arriba.', 'Auf demselben Bug und nicht überlappend hält sich das hintere Boot vom vorderen frei. Holst du in Luv auf, bist du das Luvboot; in Lee, und das Boot voraus hält sich nun von dir frei – beachte Regel 17 oben.', 'Aynı kontrada ve bindirmesiz olarak, arkadaki tekne öndeki tekneden uzak durur. Rüzgârüstünden yetişirsen rüzgârüstü tekne sensin; rüzgâraltından yetişirsen öndeki tekne artık senden uzak durur. Yukarıdaki kural 17’ye dikkat.', 'Sur le même bord et non engagés, le bateau derrière se maintient à l’écart du bateau devant. Rattrape-le au vent et tu es le bateau au vent ; sous le vent, et c’est le bateau devant qui doit désormais se maintenir à l’écart de toi — attention à la règle 17 plus haut.'),
      ] },
      { id: 'r13', h: t('Tacking boats keep clear (rules 13, 15, 16)', 'Поворачивающая уступает (правила 13, 15, 16)', 'Los barcos que viran se mantienen separados (reglas 13, 15, 16)', 'Wendende Boote halten sich frei (Regeln 13, 15, 16)', 'Tramola atan tekneler uzak durur (kurallar 13, 15, 16)', 'Le bateau qui vire se maintient à l’écart (règles 13, 15, 16)'), p: [
        t('From passing head to wind until she is on a close-hauled course, a tacking boat keeps clear of everyone. Tack too close in front of a starboard boat and the foul is yours.',
          'С момента, когда лодка прошла положение левентик, и пока не легла в бейдевинд, она уступает всем. Повернула слишком близко перед лодкой правого галса — нарушение твоё.', 'Desde que pasa proa al viento hasta que está en rumbo de ceñida, un barco que vira se mantiene separado de todos. Vira demasiado cerca por delante de un barco de estribor y la falta es tuya.', 'Vom Durchgang durch den Wind, bis es auf einem Hoch-am-Wind-Kurs liegt, hält sich ein wendendes Boot von allen frei. Wende zu dicht vor einem Steuerbordboot, und das Foul ist deins.', 'Başı rüzgâra getirdiği andan orsa rotasına gelene kadar, tramola atan tekne herkesten uzak durur. Sancaktaki bir teknenin hemen önünde tramola atarsan ihlal senindir.', 'Du moment où il passe bout au vent jusqu’à ce qu’il soit au près serré, un bateau qui vire se maintient à l’écart de tous. Vire trop près devant un bateau tribord et la faute est pour toi.'),
        t('Right of way comes with duties: a boat that gains it must at first give the other room to keep clear (rule 15), and a right-of-way boat that changes course must still leave the other room to keep clear (rule 16).',
          'У права дороги есть обязанности: лодка, получившая его, сначала должна дать другой место, чтобы уступить (правило 15), а лодка с правом дороги, меняя курс, должна оставлять другой место, чтобы уступить (правило 16).', 'El derecho de paso trae obligaciones: un barco que lo adquiere debe dar al otro, al principio, espacio para mantenerse separado (regla 15), y un barco con derecho de paso que cambia de rumbo debe dejar igualmente al otro espacio para mantenerse separado (regla 16).', 'Wegerecht bringt Pflichten mit: Ein Boot, das es erwirbt, muss dem anderen zunächst Raum geben, sich freizuhalten (Regel 15), und ein Boot mit Wegerecht, das den Kurs ändert, muss dem anderen trotzdem Raum lassen, sich freizuhalten (Regel 16).', 'Geçiş hakkı sorumluluklarla gelir: onu kazanan tekne başlangıçta ötekine uzak durması için alan vermelidir (kural 15) ve rotasını değiştiren geçiş hakkı sahibi tekne yine de ötekine uzak durması için alan bırakmalıdır (kural 16).', 'La priorité s’accompagne de devoirs : un bateau qui l’acquiert doit d’abord laisser à l’autre la place de se maintenir à l’écart (règle 15), et un bateau prioritaire qui change de route doit quand même laisser à l’autre la place de se maintenir à l’écart (règle 16).'),
      ], tip: t('Before you tack near another boat, make sure you’ll be close-hauled on the new tack before she has to change course to avoid you. If in doubt, sail on a few more lengths.',
        'Прежде чем поворачивать рядом с другой лодкой, убедись, что ляжешь в бейдевинд на новом галсе раньше, чем ей придётся менять курс, чтобы тебя избежать. Сомневаешься — пройди ещё несколько корпусов.', 'Antes de virar cerca de otro barco, asegúrate de estar de ceñida en la nueva amura antes de que él tenga que cambiar de rumbo para evitarte. Si dudas, sigue unas esloras más.', 'Bevor du in der Nähe eines anderen Bootes wendest, stelle sicher, dass du auf dem neuen Bug hoch am Wind liegst, bevor es ausweichen muss. Im Zweifel segle noch ein paar Längen weiter.', 'Başka bir teknenin yakınında tramola atmadan önce, o senden kaçınmak için rotasını değiştirmek zorunda kalmadan yeni kontrada orsada olacağından emin ol. Şüphedeysen birkaç boy daha git.', 'Avant de virer près d’un autre bateau, assure-toi d’être au près serré sur le nouveau bord avant qu’il doive changer de route pour t’éviter. Dans le doute, continue encore quelques longueurs.') },
      { id: 'r18', h: t('Room at the mark (rule 18)', 'Место у знака (правило 18)', 'Espacio en la baliza (regla 18)', 'Raum an der Bahnmarke (Regel 18)', 'Şamandırada alan (kural 18)', 'La place à la marque (règle 18)'), p: [
        t('Round every mark lies a zone three hull lengths across. When the first of two overlapped boats reaches it, the outside boat must give the inside boat room to sail round the mark. In Up and down that decides the leeward gate, where boats arrive together.',
          'Вокруг каждого знака — зона в три корпуса. Когда первая из двух связанных лодок входит в неё, внешняя должна дать внутренней место, чтобы обогнуть знак. В Up and down это решает нижние ворота, куда лодки приходят вместе.', 'Alrededor de cada baliza hay una zona de tres esloras. Cuando el primero de dos barcos con compromiso llega a ella, el barco exterior debe dar al interior espacio para navegar alrededor de la baliza. En Up and down eso decide la puerta de sotavento, donde los barcos llegan juntos.', 'Um jede Bahnmarke liegt eine Zone von drei Rumpflängen. Erreicht das erste von zwei überlappenden Booten sie, muss das äußere Boot dem inneren Raum geben, die Bahnmarke zu runden. In Up and down entscheidet das am Leetor, wo die Boote zusammen ankommen.', 'Her şamandıranın çevresinde üç tekne boyu genişliğinde bir bölge vardır. Bindirmeli iki teknenin ilki oraya ulaştığında, dıştaki tekne içtekine şamandırayı dönmesi için alan vermelidir. Up and down’da bu, teknelerin birlikte vardığı rüzgâraltı kapısında belirleyicidir.', 'Autour de chaque bouée s’étend une zone de trois longueurs de coque. Quand le premier de deux bateaux engagés l’atteint, le bateau à l’extérieur doit donner au bateau à l’intérieur la place de passer la bouée. Dans Up and down, c’est ce qui décide à la porte sous le vent, où les bateaux arrivent ensemble.'),
        t('Rule 18 does not apply between boats on opposite tacks on a beat, so at the windward mark the port and starboard rule still decides. And tack inside the zone at your peril: you must not make a boat that has been on starboard since entering the zone sail above close-hauled (rule 18.3).',
          'Между лодками на разных галсах на лавировке правило 18 не действует, так что у верхнего знака по-прежнему решает правило галсов. А поворот внутри зоны опасен: нельзя заставить лодку, которая идёт правым галсом с момента входа в зону, идти круче бейдевинда (правило 18.3).', 'La regla 18 no se aplica entre barcos en amuras opuestas en una ceñida, así que en la baliza de barlovento sigue decidiendo la regla de babor y estribor. Y vira dentro de la zona bajo tu responsabilidad: no debes obligar a un barco que está en estribor desde que entró en la zona a navegar por encima de la ceñida (regla 18.3).', 'Regel 18 gilt nicht zwischen Booten auf entgegengesetzten Bugen am Wind, also entscheidet an der Luvtonne weiter die Regel Backbord gegen Steuerbord. Und wende in der Zone auf eigene Gefahr: Du darfst ein Boot, das seit dem Erreichen der Zone auf Steuerbord segelt, nicht zwingen, höher als hoch am Wind zu segeln (Regel 18.3).', 'Kural 18, orsa ayağında zıt kontradaki tekneler arasında geçerli değildir; yani rüzgârüstü şamandırasında iskele ve sancak kuralı yine karar verir. Bölgenin içinde tramola atmak da tehlikelidir: bölgeye girdiğinden beri sancakta olan bir tekneyi orsadan daha yukarı yelken açmaya zorlamamalısın (kural 18.3).', 'La règle 18 ne s’applique pas entre bateaux sur des bords opposés au près : à la bouée au vent, c’est donc toujours la règle bâbord-tribord qui décide. Et vire dans la zone à tes risques et périls : tu ne dois pas obliger un bateau qui est tribord amures depuis son entrée dans la zone à naviguer au-dessus du près serré (règle 18.3).'),
      ], tip: t('Not sure you got the inside overlap before the zone? Assume you didn’t: where there is reasonable doubt, rule 18 presumes the overlap wasn’t made in time.',
        'Не уверен, что успел установить внутреннюю связанность до зоны? Считай, что не успел: при обоснованном сомнении правило 18 исходит из того, что связанность вовремя не установлена.', '¿No estás seguro de haber conseguido el compromiso interior antes de la zona? Supón que no: si hay duda razonable, la regla 18 presume que el compromiso no se hizo a tiempo.', 'Nicht sicher, ob du die innere Überlappung vor der Zone hattest? Nimm an, du hattest sie nicht: Bei begründetem Zweifel wird nach Regel 18 vermutet, dass die Überlappung nicht rechtzeitig bestand.', 'İç bindirmeyi bölgeden önce kurduğundan emin değil misin? Kurmadığını varsay: makul şüphe varsa kural 18, bindirmenin zamanında kurulmadığını varsayar.', 'Pas sûr d’avoir pris l’engagement intérieur avant la zone ? Pars du principe que non : en cas de doute raisonnable, la règle 18 présume que l’engagement n’a pas été établi à temps.') },
      { id: 'pen', h: t('Fouls and penalties (rules 31, 43, 44)', 'Нарушения и штрафы (правила 31, 43, 44)', 'Faltas y penalizaciones (reglas 31, 43, 44)', 'Fouls und Strafen (Regeln 31, 43, 44)', 'İhlaller ve cezalar (kurallar 31, 43, 44)', 'Fautes et pénalités (règles 31, 43, 44)'), p: [
        t('Break a rule of Part 2 and you can take a penalty at once instead of a protest: get clear of the other boats and turn through a tack and a gybe. Touching a mark is a foul too (rule 31). Real races usually ask for two turns for a foul between boats and one for a mark, unless the sailing instructions say otherwise; the game asks for one turn either way, and disqualifies a boat that finishes without taking it.',
          'Нарушил правило части 2 — можешь сразу отработать штраф вместо протеста: отойди от других лодок и сделай оборот через поворот оверштаг и фордевинд. Касание знака — тоже нарушение (правило 31). В настоящих гонках за нарушение против лодки обычно положено два оборота, за знак — один, если гоночная инструкция не говорит иначе; в игре — один оборот в любом случае, а лодка, финишировавшая без штрафа, дисквалифицируется.', 'Infringe una regla de la Parte 2 y puedes cumplir una penalización enseguida en lugar de una protesta: sepárate de los demás barcos y haz un giro con una virada y una trasluchada. Tocar una baliza también es una falta (regla 31). En las regatas reales suelen pedirse dos giros por una falta entre barcos y uno por una baliza, salvo que las instrucciones de regata digan otra cosa; el juego pide un giro en ambos casos y descalifica al barco que llega sin hacerlo.', 'Verstößt du gegen eine Regel aus Teil 2, kannst du statt eines Protests sofort eine Strafe nehmen: Komm von den anderen Booten frei und drehe eine Wende und eine Halse. Auch das Berühren einer Bahnmarke ist ein Foul (Regel 31). In echten Regatten sind meist zwei Kringel für ein Foul zwischen Booten und einer für eine Bahnmarke vorgesehen, sofern die Segelanweisungen nichts anderes sagen; das Spiel verlangt in beiden Fällen einen Kringel und disqualifiziert ein Boot, das ohne ihn ins Ziel kommt.', '2. Bölüm’ün bir kuralını çiğnersen protesto yerine hemen ceza alabilirsin: diğer teknelerden açığa çık ve bir tramola ve bir kavançayla dön. Şamandıraya dokunmak da ihlaldir (kural 31). Gerçek yarışlar, yarış talimatı başka türlü demedikçe genellikle tekneler arası ihlal için iki, şamandıra için bir dönüş ister; oyun her ikisi için de tek dönüş ister ve bunu almadan bitiren tekneyi diskalifiye eder.', 'Enfreins une règle de la partie 2 et tu peux effectuer une pénalité tout de suite au lieu d’une réclamation : dégage-toi des autres bateaux et fais un tour avec un virement de bord et un empannage. Toucher une bouée est aussi une faute (règle 31). Les vraies régates demandent en général deux tours pour une faute entre bateaux et un pour une marque, sauf si les instructions de course disent autre chose ; le jeu demande un tour dans les deux cas, et disqualifie un bateau qui finit sans l’avoir fait.'),
        t('If another boat’s foul forced you into one, you are exonerated and take no penalty (rule 43).',
          'Если тебя вынудило нарушить чужое нарушение, ты освобождаешься от ответственности и штраф не берёшь (правило 43).', 'Si la falta de otro barco te obligó a cometer una, quedas exonerado y no tienes penalización (regla 43).', 'Hat dich das Foul eines anderen Bootes dazu gezwungen, bist du entlastet und nimmst keine Strafe (Regel 43).', 'Bir başka teknenin ihlali seni buna zorladıysa aklanırsın ve ceza almazsın (kural 43).', 'Si la faute d’un autre bateau t’a forcé à en commettre une, tu es exonéré et ne fais pas de pénalité (règle 43).'),
      ], tip: t('Get clear first, then turn the same way all round, through a tack and a gybe. In the game, turning back the other way starts the turn again; and while you take a penalty, you keep clear of every boat that isn’t (rule 21.2).',
        'Сначала отойди от других, потом крутись в одну сторону — через оверштаг и фордевинд. В игре поворот обратно в другую сторону начинает оборот заново; а пока ты отрабатываешь штраф, ты уступаешь всем, кто его не отрабатывает (правило 21.2).', 'Primero sepárate, luego gira siempre hacia el mismo lado, con una virada y una trasluchada. En el juego, girar de vuelta al otro lado reinicia el giro; y mientras cumples una penalización, te mantienes separado de todos los barcos que no lo hacen (regla 21.2).', 'Komm zuerst frei, dann drehe ganz in eine Richtung, durch eine Wende und eine Halse. Im Spiel beginnt die Drehung von vorn, wenn du zurückdrehst; und solange du eine Strafe nimmst, hältst du dich von jedem Boot frei, das keine nimmt (Regel 21.2).', 'Önce açığa çık, sonra hep aynı yöne dön: bir tramola ve bir kavançayla. Oyunda geri diğer yöne dönmek dönüşü yeniden başlatır; ve sen ceza alırken, almayan her tekneden uzak durursun (kural 21.2).', 'Dégage-toi d’abord, puis tourne dans le même sens tout du long, avec un virement de bord et un empannage. Dans le jeu, repartir dans l’autre sens fait recommencer le tour ; et pendant que tu effectues une pénalité, tu te maintiens à l’écart de tout bateau qui n’en effectue pas (règle 21.2).'), pen: true },
    ],
    more: [
      { label: t('Right of way, rule by rule', 'Право дороги, правило за правилом', 'Derecho de paso, regla por regla', 'Wegerecht, Regel für Regel', 'Geçiş hakkı, kural kural', 'La priorité, règle par règle'), href: rr(lang, 'rightofway') },
      { label: t('Room at marks', 'Место у знаков', 'Espacio en las balizas', 'Raum an Bahnmarken', 'Şamandıralarda alan', 'La place aux bouées'), href: rr(lang, 'marks') },
      { label: t('Penalties', 'Штрафы', 'Penalizaciones', 'Strafen', 'Cezalar', 'Pénalités'), href: rr(lang, 'penalties') },
    ],
    try: { label: t('Sail today’s race', 'Пройди гонку дня', 'Navega la regata del día', 'Die Regatta des Tages segeln', 'Günün yarışına çık', 'Cours la régate du jour'), href: '/race', text: t(
      'Five computer boats that hail, give way and spin their penalty turns. After the finish, the result shows every foul with the rule behind it.',
      'Пять компьютерных лодок, которые окликают, уступают и крутят штрафные обороты. После финиша в результате видно каждое нарушение и правило за ним.', 'Cinco barcos del ordenador que gritan, ceden el paso y hacen sus giros de penalización. Tras la llegada, el resultado muestra cada falta con la regla que hay detrás.', 'Fünf Computerboote, die rufen, ausweichen und ihre Strafkringel drehen. Nach dem Ziel zeigt das Ergebnis jedes Foul mit der Regel dahinter.', 'Çağıran, yol veren ve ceza dönüşlerini yapan beş bilgisayar teknesi. Bitişten sonra sonuç, her ihlali arkasındaki kuralla birlikte gösterir.', 'Cinq bateaux de l’ordinateur qui hèlent, cèdent le passage et font leurs tours de pénalité. Après l’arrivée, le résultat montre chaque faute avec la règle en cause.') },
  };

  if (slug === 'start') return {
    slug,
    title: t('How to win a sailing start', 'Как выиграть старт в парусной гонке', 'Cómo ganar una salida en vela', 'So gewinnst du einen Segelstart', 'Yelken yarışında startı nasıl kazanırsın', 'Comment gagner un départ de régate'),
    short: t('How to win the start', 'Как выиграть старт', 'Cómo ganar la salida', 'So gewinnst du den Start', 'Startı nasıl kazanırsın', 'Comment gagner le départ'),
    kicker: t('Racing guides · the start', 'Пособия по гонкам · старт', 'Guías de regata · la salida', 'Regattaleitfäden · der Start', 'Yarış rehberleri · start', 'Guides de régate · le départ'),
    img: shot('gd-start-v2', t('The fleet on the start line in the last seconds before the gun in the game', 'Флот на стартовой линии за секунды до сигнала в игре', 'La flota en la línea de salida en los últimos segundos antes de la señal de salida en el juego', 'Das Feld an der Startlinie in den letzten Sekunden vor dem Startsignal im Spiel', 'Oyunda start işaretinden önceki son saniyelerde start hattındaki filo', 'La flotte sur la ligne de départ dans les dernières secondes avant le coup de canon, dans le jeu'), 3840, 1600),
    description: t(
      'How to start a sailing race well: the flags and signals, finding the favoured end of the line, timing your run, holding your spot, what to do when you are over early, and clear air after the gun.',
      'Как хорошо стартовать в парусной гонке: флаги и сигналы, выгодный конец линии, расчёт разгона, как удержать место, что делать при фальстарте и чистый ветер после сигнала.', 'Cómo salir bien en una regata de vela: las banderas y las señales, encontrar el lado favorecido de la línea, calcular la aproximación, mantener tu sitio, qué hacer si te pasas de la línea y aire limpio tras la señal.', 'So startest du eine Segelregatta gut: die Flaggen und Signale, das begünstigte Ende der Linie finden, den Anlauf timen, deinen Platz halten, was zu tun ist, wenn du zu früh drüber bist, und freier Wind nach dem Startsignal.', 'Bir yelken yarışına iyi nasıl start verilir: bayraklar ve işaretler, hattın avantajlı ucunu bulmak, yaklaşmanı zamanlamak, yerini tutmak, erken geçtiğinde ne yapacağın ve start işaretinden sonra temiz rüzgâr.', 'Comment bien partir en régate : les pavillons et les signaux, trouver l’extrémité favorisée de la ligne, chronométrer ta course d’élan, tenir ta place, que faire quand tu es parti trop tôt, et un vent propre après le signal.'),
    intro: t(
      'A good start puts you in front with clean wind, and a bad one leaves you in everyone’s dirty air for the whole beat. Most of it is known before the gun: which end of the line to start at, where to wait and when to go.',
      'Хороший старт выводит тебя вперёд в чистом ветре, плохой оставляет в чужой ветровой тени на всю лавировку. Многое решается до сигнала: у какого конца линии стартовать, где ждать и когда разгоняться.', 'Una buena salida te pone delante con viento limpio, y una mala te deja en el aire sucio de todos durante toda la ceñida. Casi todo se sabe antes de la señal: en qué lado de la línea salir, dónde esperar y cuándo lanzarte.', 'Ein guter Start bringt dich mit sauberem Wind nach vorn, ein schlechter lässt dich das ganze Kreuz über im Abwind aller anderen segeln. Das meiste ist schon vor dem Startsignal bekannt: an welchem Ende der Linie du startest, wo du wartest und wann du losfährst.', 'İyi bir start seni temiz rüzgârla öne koyar, kötü bir start ise bütün orsa ayağı boyunca herkesin kirli rüzgârında bırakır. Çoğu, start işaretinden önce bellidir: hattın hangi ucundan start vereceğin, nerede bekleyeceğin ve ne zaman gideceğin.', 'Un bon départ te met devant avec un vent propre, un mauvais te laisse dans le vent perturbé de tout le monde pendant tout le bord de près. L’essentiel se sait avant le signal : à quelle extrémité de la ligne partir, où attendre et quand y aller.'),
    sections: [
      { id: 'flags', h: t('The signals', 'Сигналы', 'Las señales', 'Die Signale', 'İşaretler', 'Les signaux'), p: [
        t('The race committee starts the countdown with flags over the committee boat, each with a sound. In the standard sequence (rule 26) the class flag goes up five minutes before the start, the preparatory flag at four, the preparatory comes down at one minute, and the class flag drops with the gun.',
          'Гоночный комитет ведёт отсчёт флагами на судейском судне, каждый — со звуковым сигналом. В стандартной процедуре (правило 26) флаг класса поднимают за пять минут до старта, подготовительный — за четыре, за минуту подготовительный опускают, а со стартовым сигналом опускают флаг класса.', 'El comité de regatas inicia la cuenta atrás con banderas sobre el barco del comité, cada una con un sonido. En la secuencia estándar (regla 26) la bandera de clase sube cinco minutos antes de la salida, la de preparación a los cuatro, la de preparación baja a un minuto, y la de clase baja con la señal de salida.', 'Die Wettfahrtleitung startet den Countdown mit Flaggen über dem Wettfahrtleitungsboot, jede mit einem Signalton. In der Standardfolge (Regel 26) geht die Klassenflagge fünf Minuten vor dem Start hoch, die Vorbereitungsflagge bei vier, die Vorbereitungsflagge kommt bei einer Minute herunter, und die Klassenflagge fällt mit dem Startsignal.', 'Yarış komitesi geri sayımı komite teknesinin üzerindeki bayraklarla başlatır; her birinin bir sesi vardır. Standart sırada (kural 26) sınıf bayrağı starttan beş dakika önce çıkar, hazırlık bayrağı dörtte, hazırlık bayrağı bir dakikada iner ve sınıf bayrağı start işaretiyle iner.', 'Le comité de course lance le compte à rebours avec des pavillons hissés sur le bateau comité, chacun avec un signal sonore. Dans la procédure standard (règle 26), le pavillon de classe monte cinq minutes avant le départ, le pavillon préparatoire à quatre, le préparatoire descend à une minute, et le pavillon de classe tombe avec le coup de canon.'),
        t('The preparatory flag tells you the rules for the last minute: P — be on the course side and you just go back; I — be over the line in the last minute and you must go back round one of its ends; U — be in the triangle formed by the line and the first mark in the last minute and you are disqualified; the black flag — the same, even if the start is recalled. Up and down flies all four and lets you set a 1, 3 or 5 minute sequence for a custom race.',
          'Подготовительный флаг говорит, какие правила в последнюю минуту: P — оказался за линией, просто вернись; I — оказался за линией в последнюю минуту, возвращайся в обход одного из её концов; U — оказался в последнюю минуту в треугольнике между линией и первым знаком — дисквалификация; чёрный флаг — то же, даже при общем отзыве. В Up and down есть все четыре, а в своей гонке можно выбрать процедуру на 1, 3 или 5 минут.', 'La bandera de preparación te dice las reglas del último minuto: P: si estás en el lado del recorrido, basta con volver atrás; I: si pasas la línea en el último minuto, debes volver rodeando uno de sus extremos; U: si estás en el triángulo formado por la línea y la primera baliza en el último minuto, quedas descalificado; la bandera negra: lo mismo, aunque se anule la salida. Up and down iza las cuatro y te deja elegir una secuencia de 1, 3 o 5 minutos para una regata personalizada.', 'Die Vorbereitungsflagge nennt dir die Regeln für die letzte Minute: P – bist du auf der Bahnseite, gehst du einfach zurück; I – bist du in der letzten Minute über der Linie, musst du um eines ihrer Enden zurück; U – bist du in der letzten Minute im Dreieck aus Linie und erster Bahnmarke, wirst du disqualifiziert; die schwarze Flagge – dasselbe, auch wenn der Start zurückgerufen wird. Up and down setzt alle vier und lässt dich für eine freie Regatta eine Folge von 1, 3 oder 5 Minuten einstellen.', 'Hazırlık bayrağı sana son dakikanın kurallarını söyler: P — parkur tarafındaysan geri dönersin, o kadar; I — son dakikada hattın üzerindeysen onun uçlarından birini dolaşıp geri dönmelisin; U — son dakikada hat ile ilk şamandıranın oluşturduğu üçgendeysen diskalifiye edilirsin; siyah bayrak — aynısı, start geri çağrılsa bile. Up and down dördünü de açar ve serbest bir yarış için 1, 3 ya da 5 dakikalık bir sıra ayarlamana izin verir.', 'Le pavillon préparatoire te dit les règles de la dernière minute : P — sois du côté parcours et tu reviens simplement ; I — sois au-delà de la ligne dans la dernière minute et tu dois revenir en contournant l’une de ses extrémités ; U — sois dans le triangle formé par la ligne et la première marque dans la dernière minute et tu es disqualifié ; le pavillon noir — pareil, même si le départ est rappelé. Up and down utilise les quatre et te laisse choisir une procédure de 1, 3 ou 5 minutes pour une régate libre.'),
      ], tip: t('Under P you can dip back across the line in the last minute and still start; under I you have to sail round an end, which costs you the start; under U or the black flag you can’t, so wait a length or two further back and come in with more speed.',
        'Под флагом P в последнюю минуту можно заскочить за линию, вернуться и всё равно стартовать; под I придётся обходить конец линии, и старт потерян; под U или чёрным флагом — нельзя, так что жди на корпус-два дальше и разгоняйся сильнее.', 'Con la P puedes volver a cruzar la línea en el último minuto y aun así salir; con la I tienes que rodear un extremo, y pierdes la salida; con la U o la bandera negra no, así que espera una o dos esloras más atrás y entra con más velocidad.', 'Unter P kannst du in der letzten Minute kurz über die Linie tauchen und trotzdem starten; unter I musst du um ein Ende segeln, was dich den Start kostet; unter U oder der schwarzen Flagge geht das nicht, also warte ein, zwei Längen weiter zurück und komm mit mehr Fahrt heran.', 'P altında son dakikada hattın geri tarafına dalabilir ve yine de start verebilirsin; I altında bir ucu dolaşman gerekir ve bu startı kaybettirir; U ya da siyah bayrak altında yapamazsın, bu yüzden bir iki boy daha geride bekle ve daha çok hızla gir.', 'Sous P, tu peux repasser la ligne dans la dernière minute et quand même prendre le départ ; sous I, tu dois contourner une extrémité, ce qui te coûte le départ ; sous U ou le pavillon noir, tu ne peux pas, alors attends une ou deux longueurs plus en arrière et arrive avec plus de vitesse.') },
      { id: 'end', h: t('Start at the favoured end', 'Стартуй у выгодного конца', 'Sal por el lado favorecido', 'Starte am begünstigten Ende', 'Avantajlı uçtan start ver', 'Pars à l’extrémité favorisée'), p: [
        t('A line is rarely square to the wind. The end further upwind is favoured: start there and you are ahead of everyone who started at the other end, before anyone has sailed a metre. To check, sail along the line, or turn head to wind on it — your bow points nearer the favoured end.',
          'Линия редко стоит ровно поперёк ветра. Выгоден конец, что ближе к ветру: стартовав там, ты впереди всех, кто ушёл с другого конца, ещё не пройдя ни метра. Проверить просто: пройди вдоль линии или встань на ней носом к ветру — нос укажет ближе к выгодному концу.', 'Una línea rara vez está perpendicular al viento. El extremo más a barlovento es el favorecido: sal ahí y vas por delante de todos los que salieron por el otro, antes de que nadie haya navegado un metro. Para comprobarlo, navega a lo largo de la línea, o ponte proa al viento sobre ella: tu proa apunta hacia el extremo favorecido.', 'Eine Linie liegt selten rechtwinklig zum Wind. Das weiter in Luv liegende Ende ist begünstigt: Starte dort, und du liegst vor allen, die am anderen Ende gestartet sind, bevor jemand einen Meter gesegelt ist. Zum Prüfen segle an der Linie entlang oder gehe auf ihr in den Wind – dein Bug zeigt näher zum begünstigten Ende.', 'Hat nadiren rüzgâra dik olur. Daha rüzgârüstündeki uç avantajlıdır: oradan start verirsen, kimse bir metre yelken açmadan, öteki uçtan start verenlerin hepsinin önündesindir. Kontrol etmek için hat boyunca yelken aç ya da hat üzerinde başı rüzgâra çevir; pruvan avantajlı uca daha yakın gösterir.', 'Une ligne est rarement parfaitement perpendiculaire au vent. L’extrémité la plus au vent est favorisée : pars de là et tu es devant tous ceux qui sont partis de l’autre bout, avant que personne n’ait parcouru un mètre. Pour vérifier, longe la ligne, ou mets-toi bout au vent dessus — ton étrave pointe vers l’extrémité favorisée.'),
        t('The wind shifts during the sequence, so check again in the last minutes. Up and down says which end is favoured in the bar at the top: the committee boat end or the pin.',
          'Ветер смещается и во время процедуры, так что проверь ещё раз в последние минуты. Up and down пишет выгодный конец в строке сверху: у судна или у знака.', 'El viento cambia durante la secuencia, así que vuelve a comprobarlo en los últimos minutos. Up and down indica qué extremo es el favorecido en la barra superior: el del barco del comité o el pin.', 'Der Wind dreht während der Startfolge, prüfe also in den letzten Minuten noch einmal. Up and down sagt dir in der Leiste oben, welches Ende begünstigt ist: das Wettfahrtleitungsboot-Ende oder das Pin-Ende.', 'Rüzgâr sıra boyunca döner, o yüzden son dakikalarda tekrar kontrol et. Up and down, hangi ucun avantajlı olduğunu üstteki çubukta söyler: komite teknesi ucu ya da pin.', 'Le vent bascule pendant la procédure, alors vérifie à nouveau dans les dernières minutes. Up and down indique l’extrémité favorisée dans la barre en haut : le bateau comité ou la bouée.'),
      ], tip: t('When the whole fleet piles in at the favoured end, starting a few lengths along the line, in clear air with a gap to leeward, often beats a slot in the crowd.',
        'Когда весь флот ломится к выгодному концу, старт в нескольких корпусах от него — в чистом ветре и со свободным местом под ветром — часто лучше места в толпе.', 'Cuando toda la flota se amontona en el extremo favorecido, salir unas esloras más allá en la línea, con aire limpio y un hueco a sotavento, suele ser mejor que un sitio entre la multitud.', 'Drängt sich das ganze Feld am begünstigten Ende, schlägt ein Start ein paar Längen weiter an der Linie, in freiem Wind mit einer Lücke in Lee, oft einen Platz im Gedränge.', 'Bütün filo avantajlı uca yığıldığında, hat boyunca birkaç boy ileride, rüzgâraltında bir boşlukla ve temiz rüzgârda start vermek çoğu zaman kalabalıktaki bir yerden iyidir.', 'Quand toute la flotte s’entasse à l’extrémité favorisée, partir quelques longueurs plus loin sur la ligne, dans un vent propre avec un trou sous le vent, vaut souvent mieux qu’une place dans la foule.') },
      { id: 'time', h: t('Time your run', 'Рассчитай разгон', 'Calcula tu aproximación', 'Time deinen Anlauf', 'Yaklaşmanı zamanla', 'Chronomètre ta course d’élan'), p: [
        t('The aim: on the line at full speed as the gun goes. Being on the line early and stopped is nearly as bad as being late. Know how far you are from the line and how long it takes to sail there; the game shows both, the distance and the time to the line, before the start.',
          'Цель — на линии на полной скорости в момент сигнала. Прийти рано и стоять почти так же плохо, как опоздать. Знай, сколько до линии и за сколько ты её пройдёшь; игра до старта показывает и расстояние, и время до линии.', 'El objetivo: estar en la línea a toda velocidad cuando suene la señal. Estar en la línea pronto y parado es casi tan malo como llegar tarde. Sé a qué distancia estás de la línea y cuánto tardas en llegar; el juego muestra ambas cosas, la distancia y el tiempo hasta la línea, antes de la salida.', 'Das Ziel: mit voller Fahrt auf der Linie, wenn das Startsignal fällt. Früh auf der Linie und stehend zu sein ist fast so schlecht wie zu spät. Wisse, wie weit du von der Linie entfernt bist und wie lange du dorthin brauchst; das Spiel zeigt dir beides, die Entfernung und die Zeit zur Linie, vor dem Start.', 'Amaç: start işareti geldiğinde hat üzerinde tam hızda olmak. Hat üzerinde erken ve durmuş olmak, geç kalmak kadar kötüdür. Hattan ne kadar uzakta olduğunu ve oraya yelken açmanın ne kadar sürdüğünü bil; oyun starttan önce ikisini de, hatta uzaklığı ve hatta kalan süreyi gösterir.', 'Le but : être sur la ligne à pleine vitesse au coup de canon. Être sur la ligne trop tôt et arrêté est presque aussi mauvais que d’être en retard. Sache à quelle distance tu es de la ligne et combien de temps il faut pour y arriver ; le jeu affiche les deux, la distance et le temps jusqu’à la ligne, avant le départ.'),
        t('A boat accelerates slowly from a standstill, so start your run a few lengths back and a few seconds early, then ease off if you are too soon. A boat length behind the line at the gun, going full speed, is a very good start.',
          'С места лодка разгоняется медленно, так что начинай разгон за несколько корпусов и на несколько секунд раньше, а если приходишь рано — притормози. Корпус до линии на сигнале и полная скорость — очень хороший старт.', 'Un barco acelera despacio desde parado, así que empieza tu aproximación unas esloras antes y unos segundos antes de tiempo, y suaviza si vas pronto. Una eslora por detrás de la línea en la señal, a toda velocidad, es una muy buena salida.', 'Ein Boot beschleunigt aus dem Stand langsam, beginne deinen Anlauf also ein paar Längen zurück und ein paar Sekunden früh und nimm dann Fahrt heraus, wenn du zu früh bist. Eine Bootslänge hinter der Linie beim Startsignal mit voller Fahrt ist ein sehr guter Start.', 'Bir tekne durağan halden yavaş hızlanır, bu yüzden yaklaşmana birkaç boy geride ve birkaç saniye erken başla, çok erken kalırsan gazı kes. Start işaretinde hattın bir tekne boyu gerisinde ve tam hızda olmak çok iyi bir starttır.', 'Un bateau arrêté accélère lentement : lance ta course d’élan quelques longueurs en arrière et quelques secondes en avance, puis ralentis si tu es trop tôt. Une longueur derrière la ligne au coup de canon, à pleine vitesse, c’est un très bon départ.'),
      ], tip: t('Practise a timed run before the start: sail away from the line for 30 seconds, turn and time the way back. The turn and the build-up take longer than you’d think.',
        'Потренируй разгон до старта: отойди от линии на 30 секунд, развернись и засеки, сколько идёшь обратно. Поворот и разгон занимают больше времени, чем кажется.', 'Practica una aproximación cronometrada antes de la salida: aléjate de la línea 30 segundos, gira y mide el tiempo de vuelta. El giro y la aceleración llevan más de lo que crees.', 'Übe einen getimten Anlauf vor dem Start: Segle 30 Sekunden von der Linie weg, wende und stoppe die Zeit zurück. Die Wende und das Beschleunigen dauern länger, als du denkst.', 'Starttan önce zamanlı bir yaklaşma çalış: hattan 30 saniye uzaklaş, dön ve dönüşü zamanla. Dönüş ve hız toplama sandığından uzun sürer.', 'Entraîne-toi à une course d’élan chronométrée avant le départ : éloigne-toi de la ligne pendant 30 secondes, fais demi-tour et chronomètre le retour. Le demi-tour et la relance prennent plus de temps qu’on ne croit.') },
      { id: 'hold', h: t('Hold your spot', 'Удержи место', 'Mantén tu sitio', 'Halte deinen Platz', 'Yerini tut', 'Tiens ta place'), p: [
        t('To wait near the line, head up and let the sheets right out: the boat slows and stops, and can even go backwards. Keep a gap to leeward to bear away into when it is time to accelerate, and defend it: a boat that sails into it becomes the leeward boat, and you must keep clear (rule 11).',
          'Чтобы ждать у линии, приведись и потрави шкоты до конца: лодка замедлится, остановится и может даже пойти назад. Держи свободное место под ветром, чтобы увалиться в него и разогнаться, и защищай его: лодка, которая туда зайдёт, станет подветренной, и уступать придётся тебе (правило 11).', 'Para esperar cerca de la línea, orza y suelta las escotas del todo: el barco frena y se para, e incluso puede ir hacia atrás. Mantén un hueco a sotavento para arribar cuando llegue el momento de acelerar, y defiéndelo: un barco que se mete en él pasa a ser el de sotavento, y tú debes mantenerte separado (regla 11).', 'Um nahe der Linie zu warten, luve an und fiere die Schoten ganz aus: Das Boot wird langsamer, bleibt stehen und kann sogar rückwärts gehen. Halte eine Lücke in Lee, in die du abfallen kannst, wenn es Zeit zum Beschleunigen ist, und verteidige sie: Ein Boot, das hineinsegelt, wird zum Leeboot, und du musst dich freihalten (Regel 11).', 'Hattın yakınında beklemek için orsala ve iskotaları sonuna kadar boşalt: tekne yavaşlar, durur ve hatta geriye bile gidebilir. Hızlanma zamanı geldiğinde boşlayarak gireceğin, rüzgâraltında bir boşluk bırak ve onu savun: oraya yelken açan tekne rüzgâraltı tekne olur ve sen uzak durmalısın (kural 11).', 'Pour attendre près de la ligne, lofe et choque les écoutes en grand : le bateau ralentit et s’arrête, il peut même reculer. Garde un trou sous le vent où abattre quand il est temps d’accélérer, et défends-le : un bateau qui s’y glisse devient le bateau sous le vent, et tu dois te maintenir à l’écart (règle 11).'),
        t('Close to the committee boat there is no room to be had at the start: a windward boat that tries to squeeze in between a leeward boat and the committee boat keeps clear.',
          'У судейского судна на старте места не положено: наветренная, которая пытается втиснуться между подветренной и судном, уступает.', 'Cerca del barco del comité no hay espacio que ganar en la salida: un barco de barlovento que intenta colarse entre un barco de sotavento y el barco del comité se mantiene separado.', 'Nahe dem Wettfahrtleitungsboot gibt es beim Start keinen Raum zu bekommen: Ein Luvboot, das versucht, sich zwischen ein Leeboot und das Wettfahrtleitungsboot zu zwängen, hält sich frei.', 'Komite teknesinin yakınında startta yer yoktur: rüzgâraltı tekne ile komite teknesi arasına sıkışmaya çalışan bir rüzgârüstü tekne uzak durur.', 'Près du bateau comité, il n’y a pas de place à prendre au départ : un bateau au vent qui essaie de se faufiler entre un bateau sous le vent et le bateau comité doit se maintenir à l’écart.'),
      ], tip: t('Don’t stop dead: without speed the rudder loses its grip, and you can neither bear away into your gap in time nor answer a leeward boat’s luff.',
        'Не останавливайся совсем: без хода руль теряет силу, и ты не успеешь ни увалиться в своё окно, ни ответить подветренной, когда она приводится.', 'No te pares en seco: sin velocidad el timón pierde agarre, y no puedes arribar a tu hueco a tiempo ni responder a la orzada de un barco de sotavento.', 'Bleib nicht ganz stehen: Ohne Fahrt verliert das Ruder den Halt, und du kannst weder rechtzeitig in deine Lücke abfallen noch auf das Anluven eines Leeboots reagieren.', 'Tamamen durma: hız olmadan dümen tutuşunu kaybeder ve ne boşluğuna zamanında boşlayabilirsin ne de rüzgâraltındaki bir teknenin orsalamasına cevap verebilirsin.', 'Ne t’arrête pas net : sans vitesse le safran ne tient plus, et tu ne peux ni abattre à temps dans ton trou ni répondre au lof d’un bateau sous le vent.') },
      { id: 'early', h: t('Over early', 'Фальстарт', 'Salida adelantada', 'Zu früh', 'Erken geçiş', 'Parti trop tôt'), p: [
        t('Over the line at the gun under P, the committee flies X: go back to the pre-start side and start again; the sooner you turn, the less it costs. If too many are over to tell who, the whole start is recalled (two flags, the First Substitute) and you start again.',
          'Оказался за линией на сигнале под флагом P — комитет поднимает X: вернись на предстартовую сторону и стартуй заново; чем раньше развернёшься, тем меньше потеряешь. Если за линией слишком много лодок, дают общий отзыв (флаг «Первый заменяющий») и стартуют снова.', 'Si estás sobre la línea en la señal con la P, el comité iza la X: vuelve al lado de pre-salida y sal de nuevo; cuanto antes gires, menos cuesta. Si son demasiados los que se han pasado para saber quién, se anula toda la salida (dos banderas, el Primer Repetidor) y se vuelve a salir.', 'Bist du beim Startsignal unter P über der Linie, setzt die Wettfahrtleitung X: Geh zurück auf die Vorstartseite und starte neu; je früher du drehst, desto weniger kostet es. Sind zu viele drüber, um zu sagen, wer, wird der ganze Start zurückgerufen (zwei Flaggen, der Erste Wiederholer) und ihr startet neu.', 'P altında start işaretinde hattın üzerindeysen komite X çeker: start öncesi tarafa dön ve yeniden start ver; ne kadar erken dönersen o kadar az kaybedersin. Kim olduğunu söyleyemeyecek kadar çok tekne hattın üzerindeyse, bütün start geri çağrılır (iki bayrak, Birinci Yedek) ve yeniden start verirsin.', 'Au-delà de la ligne au signal sous P, le comité envoie X : reviens du côté pré-départ et reprends le départ ; plus tôt tu fais demi-tour, moins ça coûte. S’il y a trop de bateaux au-delà pour dire lesquels, tout le départ est rappelé (deux pavillons, le premier substitut) et tu repars.'),
      ], tip: t('Going back, keep clear of every boat that is starting properly until you are wholly on the pre-start side (rule 21.1). Turn back where the fewest boats are.',
        'Возвращаясь, уступай всем, кто стартует правильно, пока целиком не окажешься на предстартовой стороне (правило 21.1). Разворачивайся там, где меньше лодок.', 'Al volver, mantente separado de todos los barcos que salen correctamente hasta que estés totalmente en el lado de pre-salida (regla 21.1). Vuelve por donde haya menos barcos.', 'Halte dich auf dem Rückweg von jedem Boot frei, das ordnungsgemäß startet, bis du ganz auf der Vorstartseite bist (Regel 21.1). Dreh dort zurück, wo die wenigsten Boote sind.', 'Geri dönerken, tamamen start öncesi tarafa gelene kadar düzgün start veren her tekneden uzak dur (kural 21.1). En az tekne olan yerde geri dön.', 'En revenant, maintiens-toi à l’écart de tout bateau qui prend correctement le départ jusqu’à ce que tu sois entièrement du côté pré-départ (règle 21.1). Fais demi-tour là où il y a le moins de bateaux.'), pen: true },
      { id: 'air', h: t('Clear air after the gun', 'Чистый ветер после старта', 'Aire limpio tras la señal', 'Freier Wind nach dem Startsignal', 'Start işaretinden sonra temiz rüzgâr', 'Un vent propre après le signal'), p: [
        t('Behind and to leeward of another boat the wind is weaker and bent: dirty air. If you are stuck in it after the start, tack away to clear wind as soon as you can safely do it. The result page counts the seconds you spent in another boat’s dirty air.',
          'За другой лодкой и под ветром от неё ветер слабее и сбит: ветровая тень. Если после старта ты в ней, поворачивай в чистый ветер, как только это безопасно. На странице результата посчитано, сколько секунд ты провёл в чужой тени.', 'Detrás y a sotavento de otro barco el viento es más débil y desviado: aire sucio. Si te quedas atrapado en él tras la salida, vira hacia viento limpio en cuanto puedas hacerlo con seguridad. La página de resultados cuenta los segundos que pasaste en el aire sucio de otro barco.', 'Hinter und in Lee eines anderen Bootes ist der Wind schwächer und abgelenkt: Abwind. Steckst du nach dem Start darin fest, wende weg in freien Wind, sobald du es sicher tun kannst. Die Ergebnisseite zählt die Sekunden, die du im Abwind eines anderen Bootes verbracht hast.', 'Başka bir teknenin gerisinde ve rüzgâraltında rüzgâr daha zayıf ve bükülmüştür: kirli rüzgâr. Starttan sonra içinde sıkışırsan, güvenle yapabilir yapmaz tramola atıp temiz rüzgâra çık. Sonuç sayfası, başka bir teknenin kirli rüzgârında geçirdiğin saniyeleri sayar.', 'Derrière et sous le vent d’un autre bateau, le vent est plus faible et dévié : c’est du vent perturbé. Si tu y es coincé après le départ, vire pour retrouver un vent propre dès que tu peux le faire sans danger. La page de résultat compte les secondes passées dans le vent perturbé d’un autre bateau.'),
      ] },
    ],
    more: [
      { label: t('Starting rules and signals', 'Правила и сигналы старта', 'Reglas y señales de salida', 'Startregeln und Signale', 'Start kuralları ve işaretleri', 'Règles et signaux de départ'), href: rr(lang, 'starting') },
      { label: t('How to play: the start', 'Как играть: старт', 'Cómo jugar: la salida', 'So spielst du: der Start', 'Nasıl oynanır: start', 'Comment jouer : le départ'), href: '/help#h-start' },
    ],
    try: { label: t('Practise the start', 'Потренируй старт', 'Practica la salida', 'Übe den Start', 'Startı çalış', 'Entraîne-toi au départ'), href: '/race/free', text: t(
      'Set a 5-minute sequence and a 7-boat fleet in a custom race, and start as often as you like.',
      'Поставь процедуру на 5 минут и флот из 7 лодок в своей гонке — и стартуй сколько хочешь.', 'Pon una secuencia de 5 minutos y una flota de 7 barcos en una regata personalizada, y sal tantas veces como quieras.', 'Stelle in einer freien Regatta eine 5-Minuten-Folge und ein Feld von 7 Booten ein und starte, so oft du willst.', 'Serbest bir yarışta 5 dakikalık bir sıra ve 7 tekneli bir filo ayarla ve istediğin kadar start ver.', 'Choisis une procédure de 5 minutes et une flotte de 7 bateaux dans une régate libre, et prends le départ autant de fois que tu veux.') },
  };

  return {
    slug,
    title: t('Headers and lifts: how to play the wind shifts', 'Заходы и отходы ветра: как их использовать', 'Roladas desfavorables y favorables: cómo jugar con las roladas', 'Dreher und Raumer: so spielst du die Winddreher', 'Aleyhte ve lehte dönüşler: rüzgâr dönüşleri nasıl oynanır', 'Refus et adonnantes : comment jouer les bascules de vent'),
    short: t('Headers and lifts', 'Заходы и отходы', 'Roladas desfavorables y favorables', 'Dreher und Raumer', 'Aleyhte ve lehte dönüşler', 'Refus et adonnantes'),
    kicker: t('Racing guides · tactics', 'Пособия по гонкам · тактика', 'Guías de regata · táctica', 'Regattaleitfäden · Taktik', 'Yarış rehberleri · taktik', 'Guides de régate · tactique'),
    img: shot('gd-shifts-v2', t('Your boat sailing upwind in the game, the wind marking the water round her', 'Твоя лодка идёт в лавировку в игре, ветер рисует полосы на воде вокруг неё', 'Tu barco navegando de ceñida en el juego, con el viento marcando el agua a su alrededor', 'Dein Boot am Wind im Spiel, der Wind zeichnet das Wasser um es herum', 'Oyunda orsa yelken açan teknen, rüzgâr çevresindeki suyu işaretliyor', 'Ton bateau au près dans le jeu, le vent qui marque l’eau autour de lui'), 3840, 1600),
    description: t(
      'How to sail the wind shifts upwind: what a header and a lift are, why you tack on the headers, when not to tack, laylines, gusts and lulls, and gybing on the lifts downwind.',
      'Как использовать сдвиги ветра на лавировке: что такое заход и отход, почему поворачивать на заходе, когда не поворачивать, лейлайны, порывы и затишья и фордевинд на отходе на попутном курсе.', 'Cómo navegar las roladas de ceñida: qué son una rolada desfavorable y una favorable, por qué se vira con las desfavorables, cuándo no virar, laylines, rachas y calmas, y trasluchar con las favorables de popa.', 'So segelst du die Winddreher am Wind: was ein Dreher und ein Raumer sind, warum du auf den Drehern wendest, wann nicht, Laylines, Böen und Flauten und Halsen auf den Raumern vor dem Wind.', 'Orsada rüzgâr dönüşleri nasıl yönetilir: aleyhte ve lehte dönüş nedir, neden aleyhte dönüşlerde tramola atılır, ne zaman atılmaz, layline’lar, hamleler ve rüzgâr kesilmeleri ve pupada lehte dönüşlerde kavança atmak.', 'Comment jouer les bascules de vent au près : ce que sont un refus et une adonnante, pourquoi virer sur les refus, quand ne pas virer, les lay-lines, les risées et les molles, et empanner sur les adonnantes au portant.'),
    intro: t(
      'The wind never blows from one direction for long. It swings a few degrees, then ten or more, back and forth every minute or so. Upwind, a boat that tacks on those shifts sails a shorter way to the mark than one that just sails the same distance on each tack — often by more than any boat speed can make up.',
      'Ветер никогда долго не дует с одного направления. Он гуляет на несколько градусов, потом на десять и больше — туда и обратно примерно каждую минуту. На лавировке лодка, которая поворачивает на этих заходах, проходит до знака более короткий путь, чем та, что просто делает равные галсы, — часто больше, чем можно отыграть скоростью.', 'El viento nunca sopla mucho tiempo desde una sola dirección. Oscila unos grados, luego diez o más, de un lado a otro cada minuto más o menos. De ceñida, un barco que vira con esas roladas navega un camino más corto hacia la baliza que uno que simplemente navega la misma distancia en cada amura, a menudo por más de lo que cualquier velocidad del barco puede compensar.', 'Der Wind weht nie lange aus einer Richtung. Er schwingt ein paar Grad, dann zehn oder mehr, etwa jede Minute hin und her. Ein Boot, das am Wind auf diesen Drehern wendet, segelt einen kürzeren Weg zur Bahnmarke als eines, das auf jedem Bug nur dieselbe Strecke segelt – oft um mehr, als jede Bootsgeschwindigkeit ausgleichen kann.', 'Rüzgâr hiçbir zaman uzun süre tek yönden esmez. Birkaç derece, sonra on ya da daha fazla, yaklaşık dakikada bir ileri geri döner. Orsada bu dönüşlerde tramola atan tekne, her kontrada aynı mesafeyi giden tekneden şamandıraya daha kısa bir yol yelken açar; çoğu zaman hiçbir tekne hızının kapatabileceğinden fazla.', 'Le vent ne souffle jamais longtemps de la même direction. Il tourne de quelques degrés, puis de dix ou plus, d’un côté puis de l’autre, à peu près chaque minute. Au près, un bateau qui vire sur ces bascules parcourt un chemin plus court jusqu’à la bouée qu’un bateau qui fait simplement la même distance sur chaque bord — souvent de plus que ce qu’aucune vitesse ne peut rattraper.'),
    sections: [
      { id: 'what', h: t('Header or lift', 'Заход или отход', 'Desfavorable o favorable', 'Dreher oder Raumer', 'Aleyhte mi lehte mi', 'Refus ou adonnante'), p: [
        t('Sailing close-hauled, a header is a shift that comes from further ahead: to keep the sails full you have to bear away, and you point further from the mark. A lift comes from further aft: you can head up and point closer to the mark.',
          'В бейдевинд заход ветра — это сдвиг ветра к носу: чтобы паруса не заполаскивали, приходится уваливаться, и ты идёшь дальше от знака. Отход — сдвиг к корме: можно привестись и идти ближе к знаку.', 'De ceñida, una rolada desfavorable es un cambio que viene de más adelante: para mantener las velas llenas tienes que arribar, y apuntas más lejos de la baliza. Una rolada favorable viene de más atrás: puedes orzar y apuntar más cerca de la baliza.', 'Hoch am Wind ist ein Dreher ein Winddreher, der von weiter vorn kommt: Um die Segel voll zu halten, musst du abfallen und zeigst weiter von der Bahnmarke weg. Ein Raumer kommt von weiter achtern: Du kannst anluven und zeigst näher zur Bahnmarke.', 'Orsada giderken aleyhte dönüş, daha önden gelen bir dönüştür: yelkenleri dolu tutmak için boşlaman gerekir ve şamandıradan daha uzağa yönelirsin. Lehte dönüş daha arkadan gelir: orsalayabilir ve şamandıraya daha yakın yönelebilirsin.', 'Au près serré, un refus est une bascule qui vient de plus en avant : pour garder les voiles pleines, tu dois abattre, et tu pointes plus loin de la bouée. Une adonnante vient de plus en arrière : tu peux lofer et pointer plus près de la bouée.'),
        t('A header on one tack is a lift on the other. That is the whole trick.',
          'Заход на одном галсе — это отход на другом. В этом весь секрет.', 'Una rolada desfavorable en una amura es favorable en la otra. Ese es todo el truco.', 'Ein Dreher auf einem Bug ist ein Raumer auf dem anderen. Das ist der ganze Trick.', 'Bir kontradaki aleyhte dönüş, öteki kontrada lehte dönüştür. Bütün hile budur.', 'Un refus sur un bord est une adonnante sur l’autre. Tout le secret est là.'),
      ], tip: t('Learn your two headings: in a steady moment, note where your bow points close-hauled on each tack. Pointing lower than that later is a header; higher, a lift.',
        'Запомни два курса: в спокойный момент заметь, куда смотрит нос в бейдевинд на каждом галсе. Позже нос ниже этого — заход, выше — отход.', 'Aprende tus dos rumbos: en un momento estable, anota hacia dónde apunta tu proa de ceñida en cada amura. Apuntar más bajo que eso después es una rolada desfavorable; más alto, una favorable.', 'Lerne deine beiden Kurse: Merke dir in einem stetigen Moment, wohin dein Bug hoch am Wind auf jedem Bug zeigt. Zeigst du später tiefer, ist es ein Dreher; höher, ein Raumer.', 'İki rotanı öğren: durağan bir anda, pruvanın her kontrada orsada nereyi gösterdiğini not et. Sonradan bundan daha aşağıya yönelmek aleyhte, daha yukarıya yönelmek lehte dönüştür.', 'Retiens tes deux caps : dans un moment de vent stable, note où pointe ton étrave au près serré sur chaque bord. Pointer plus bas que ça ensuite, c’est un refus ; plus haut, une adonnante.') },
      { id: 'tack', h: t('Tack on the headers', 'Поворачивай на заходе', 'Vira con las desfavorables', 'Wende auf den Drehern', 'Aleyhte dönüşlerde tramola at', 'Vire sur les refus'), p: [
        t('When you are headed, tack: on the new tack the same shift lifts you, and you sail towards the mark at a better angle. Stay on the tack that points you closer to the mark, and you are always on the lifted one.',
          'Когда ветер зашёл — поворачивай: на новом галсе тот же сдвиг станет отходом, и ты пойдёшь к знаку под лучшим углом. Держись галса, который ведёт ближе к знаку, — и ты всегда на выгодном.', 'Cuando te rola en contra, vira: en la nueva amura el mismo cambio te favorece, y navegas hacia la baliza con mejor ángulo. Quédate en la amura que te apunta más cerca de la baliza, y estarás siempre en la favorecida.', 'Wirst du abgedreht, wende: Auf dem neuen Bug hebt dich derselbe Dreher, und du segelst in besserem Winkel zur Bahnmarke. Bleibe auf dem Bug, der dich näher zur Bahnmarke zeigt, und du bist immer im Raumer.', 'Aleyhte dönüş aldığında tramola at: yeni kontrada aynı dönüş seni lehte alır ve şamandıraya daha iyi bir açıyla yelken açarsın. Seni şamandıraya yaklaştıran kontrada kal, hep lehte olandasın.', 'Quand tu es refusé, vire : sur le nouveau bord, la même bascule te fait adonner, et tu fais route vers la bouée avec un meilleur angle. Reste sur le bord qui te fait pointer le plus près de la bouée, et tu es toujours sur le bord adonnant.'),
        t('In Up and down the wind box says which you are in on the beat: Header in orange, Lift in green. After the race, the result counts your tacks in headers and in lifts.',
          'В Up and down окно ветра на лавировке говорит, что сейчас: «Заход» оранжевым, «Отход» зелёным. После гонки в результате посчитано, сколько поворотов ты сделал на заходе и сколько на отходе.', 'En Up and down el cuadro del viento te dice en cuál estás en la ceñida: «Desfavorable» en naranja, «Favorable» en verde. Tras la regata, el resultado cuenta tus viradas en roladas desfavorables y en favorables.', 'In Up and down sagt dir die Windanzeige am Wind, in welchem du bist: Dreher in Orange, Raumer in Grün. Nach der Regatta zählt das Ergebnis deine Wenden in Drehern und in Raumern.', 'Up and down’da rüzgâr kutusu orsada hangisinde olduğunu söyler: Aleyhte turuncu, Lehte yeşil. Yarıştan sonra sonuç, tramolalarını aleyhte ve lehte dönüşlerde sayar.', 'Dans Up and down, l’encart du vent indique au près où tu en es : Refus en orange, Adonnante en vert. Après la régate, le résultat compte tes virements dans les refus et dans les adonnantes.'),
      ] },
      { id: 'dont', h: t('When not to tack', 'Когда не поворачивать', 'Cuándo no virar', 'Wann nicht wenden', 'Ne zaman tramola atılmaz', 'Quand ne pas virer'), p: [
        t('Every tack costs a few boat lengths while the boat slows and builds speed again. A shift of two or three degrees that lasts ten seconds isn’t worth one. Wait until the header is real — and don’t tack into another boat’s dirty air, or onto port across a fleet on starboard.',
          'Каждый поворот стоит нескольких корпусов, пока лодка теряет и снова набирает скорость. Сдвиг на два-три градуса на десять секунд того не стоит. Дождись настоящего захода — и не поворачивай в чужую ветровую тень или левым галсом поперёк флота на правом.', 'Cada virada cuesta unas esloras mientras el barco frena y vuelve a acelerar. Un cambio de dos o tres grados que dura diez segundos no la merece. Espera a que la rolada desfavorable sea real, y no vires hacia el aire sucio de otro barco, ni a babor cruzando una flota de estribor.', 'Jede Wende kostet ein paar Bootslängen, während das Boot langsamer wird und wieder Fahrt aufbaut. Ein Dreher von zwei, drei Grad, der zehn Sekunden anhält, ist keine wert. Warte, bis der Dreher echt ist – und wende nicht in den Abwind eines anderen Bootes oder auf Backbord quer vor ein Feld auf Steuerbord.', 'Her tramola, tekne yavaşlayıp yeniden hız toplarken birkaç tekne boyuna mal olur. On saniye süren iki üç derecelik bir dönüş buna değmez. Aleyhte dönüş gerçek olana kadar bekle; ve başka bir teknenin kirli rüzgârına ya da sancaktaki bir filonun önünden iskeleye tramola atma.', 'Chaque virement coûte quelques longueurs, le temps que le bateau ralentisse et reprenne de la vitesse. Une bascule de deux ou trois degrés qui dure dix secondes n’en vaut pas un. Attends que le refus soit réel — et ne vire pas dans le vent perturbé d’un autre bateau, ni bâbord amures en travers d’une flotte tribord amures.'),
      ], tip: t('Judge a shift against the wind’s average over the last minute or two, not against the last puff. Tack once you are headed past the middle, not at the first wobble.',
        'Сравнивай сдвиг со средним ветром за последнюю минуту-две, а не с последним дуновением. Поворачивай, когда заход ушёл за середину, а не при первом колебании.', 'Juzga un cambio frente al promedio del viento en el último minuto o dos, no frente a la última racha. Vira cuando te rola en contra más allá de la mitad, no al primer titubeo.', 'Beurteile einen Dreher am Durchschnitt des Windes der letzten ein, zwei Minuten, nicht an der letzten Bö. Wende, sobald du über die Mitte hinaus abgedreht wirst, nicht beim ersten Wackeln.', 'Bir dönüşü, son puftaki değil, son bir iki dakikadaki rüzgârın ortalamasına göre değerlendir. Orta noktanın ötesinde aleyhte kaldığında tramola at, ilk sallanmada değil.', 'Juge une bascule par rapport à la moyenne du vent sur la dernière minute ou les deux dernières, pas par rapport à la dernière risée. Vire une fois refusé au-delà de la moyenne, pas au premier frémissement.') },
      { id: 'lay', h: t('Stay off the laylines', 'Не выходи на лейлайн рано', 'Aléjate de las laylines', 'Bleibe von den Laylines weg', 'Layline’lardan uzak dur', 'Reste loin des lay-lines'), p: [
        t('A layline is the line from which you can just fetch the mark on one tack. Reach it early and every shift works against you: a header and you have to tack again, a lift and you have sailed too far. Keep to the middle of the course until the last part of the beat. The game’s top view draws the laylines.',
          'Лейлайн — линия, с которой знак берётся одним галсом. Выйдешь на неё рано — и любой сдвиг против тебя: заход — придётся поворачивать снова, отход — ты прошёл лишнее. Держись середины дистанции до конца лавировки. В виде сверху игра рисует лейлайны.', 'Una layline es la línea desde la que justo puedes llegar a la baliza en una amura. Llega a ella pronto y cada rolada juega en tu contra: una desfavorable y tienes que virar otra vez, una favorable y has navegado de más. Mantente en el centro del recorrido hasta la última parte de la ceñida. La vista aérea del juego dibuja las laylines.', 'Eine Layline ist die Linie, von der aus du die Bahnmarke gerade noch auf einem Bug anliegen kannst. Erreichst du sie früh, arbeitet jeder Dreher gegen dich: Ein Dreher, und du musst nochmals wenden, ein Raumer, und du bist zu weit gesegelt. Bleibe bis zum letzten Teil des Kreuzes in der Mitte der Bahn. Die Draufsicht des Spiels zeichnet die Laylines.', 'Layline, şamandırayı tek kontrada tam yetişebildiğin çizgidir. Ona erken varırsan her dönüş sana karşı çalışır: aleyhte dönüş ve yeniden tramola atman gerekir, lehte dönüş ve fazla yol yelken açmışsındır. Orsanın son kısmına kadar parkurun ortasında kal. Oyunun üstten görünümü layline’ları çizer.', 'Une lay-line est la ligne d’où tu peux tout juste atteindre la bouée sur un seul bord. Atteins-la trop tôt et chaque bascule joue contre toi : un refus et tu dois revirer, une adonnante et tu es allé trop loin. Reste au milieu du plan d’eau jusqu’à la dernière partie du bord de près. La vue de dessus du jeu trace les lay-lines.'),
      ], tip: t('Overstood the mark? Don’t tack back: ease the sheets a little and reach in. It costs a few lengths; two more tacks cost more.',
        'Перебрал лейлайн? Не поворачивай обратно: чуть потрави шкоты и иди на знак полнее. Это несколько корпусов, а два лишних поворота — больше.', '¿Te has pasado de la baliza? No vires de vuelta: lasca un poco las escotas y entra de través. Cuesta unas esloras; dos viradas más cuestan más.', 'Die Bahnmarke überstanden? Wende nicht zurück: Fiere die Schoten ein wenig und segle raumschots hinein. Das kostet ein paar Längen; zwei weitere Wenden kosten mehr.', 'Şamandırayı aştın mı? Geri tramola atma: iskotaları biraz boşalt ve apazla gir. Birkaç boya mal olur; iki tramola daha fazlasına mal olur.', 'Tu as dépassé la lay-line ? Ne revire pas : choque un peu les écoutes et arrive au débridé. Ça coûte quelques longueurs ; deux virements de plus coûtent davantage.') },
      { id: 'gusts', h: t('Gusts and lulls', 'Порывы и затишья', 'Rachas y calmas', 'Böen und Flauten', 'Hamleler ve rüzgâr kesilmeleri', 'Risées et molles'), p: [
        t('A gust shows as darker water coming down the course. Upwind in a gust the boat heels and can point higher; in a lull bear away a little to keep her speed up. In a strong breeze, reef the main or change to the small jib before she heels too far.',
          'Порыв видно как тёмную рябь, идущую по дистанции. На лавировке в порыве лодка кренится и может идти круче; в затишье увались немного, чтобы держать скорость. В сильный ветер возьми риф на гроте или поставь малый стаксель, пока крен не стал слишком большим.', 'Una racha se ve como agua más oscura bajando por el recorrido. De ceñida en una racha el barco escora y puede apuntar más alto; en una calma arriba un poco para mantener la velocidad. Con brisa fuerte, riza la mayor o cambia al foque pequeño antes de que escore demasiado.', 'Eine Bö zeigt sich als dunkleres Wasser, das die Bahn herunterkommt. Am Wind in einer Bö krängt das Boot und kann höher segeln; in einer Flaute falle ein wenig ab, um die Fahrt zu halten. Reffe bei starkem Wind das Groß oder wechsle auf die kleine Fock, bevor das Boot zu weit krängt.', 'Bir hamle, parkurdan inen daha koyu su olarak görünür. Orsada hamlede tekne yatar ve daha yükseğe gidebilir; rüzgâr kesilince hızı korumak için biraz boşla. Güçlü rüzgârda, fazla yatmadan önce ana yelkenden camada al ya da küçük floka geç.', 'Une risée se voit comme une eau plus sombre qui descend le plan d’eau. Au près dans une risée, le bateau gîte et peut serrer plus le vent ; dans une molle, abats un peu pour garder sa vitesse. Dans la brise forte, prends un ris dans la grand-voile ou passe au petit foc avant qu’il ne gîte trop.'),
      ], tip: t('One side of the course often has more wind for the whole race, in the game too. Find out which on the first beat, and go there on the next.',
        'На одной стороне дистанции ветра часто больше всю гонку — в игре тоже. Выясни на первой лавировке, на какой, и иди туда на следующих.', 'Un lado del recorrido suele tener más viento durante toda la regata, también en el juego. Descubre cuál en la primera ceñida, y ve allí en la siguiente.', 'Eine Seite der Bahn hat oft die ganze Regatta über mehr Wind, im Spiel auch. Finde auf dem ersten Kreuz heraus, welche, und geh beim nächsten dorthin.', 'Parkurun bir tarafında çoğu zaman bütün yarış boyunca daha çok rüzgâr olur, oyunda da. İlk orsa ayağında hangisi olduğunu bul ve bir sonrakinde oraya git.', 'Un côté du plan d’eau a souvent plus de vent pendant toute la régate, dans le jeu aussi. Repère lequel au premier bord de près, et vas-y au suivant.') },
      { id: 'down', h: t('Downwind: gybe on the lifts', 'На попутном: фордевинд на отходе', 'De popa: trasluca con las favorables', 'Vor dem Wind: Halse auf den Raumern', 'Pupada: lehte dönüşlerde kavança at', 'Au portant : empanne sur les adonnantes'), p: [
        t('On the run it works the other way round. A lift makes you head up, away from the mark, to keep the same angle to the wind; gybe and the shift points you at the mark again. On a sea-breeze day the wind also builds and swings right as the race goes on, so the right side of the course often pays (south of the equator it swings left, and the left side does).',
          'На попутном всё наоборот. Отход заставляет приводиться, уходя от знака, чтобы сохранить угол к ветру; сделай фордевинд — и тот же сдвиг снова поведёт тебя к знаку. А в день морского бриза ветер к тому же усиливается и смещается вправо по ходу гонки, так что правая сторона дистанции часто выгоднее (южнее экватора он смещается влево, и выгоднее левая).', 'En la empopada funciona al revés. Una rolada favorable te hace orzar, alejándote de la baliza, para mantener el mismo ángulo con el viento; trasluca y el cambio te apunta de nuevo a la baliza. En un día de brisa térmica el viento además aumenta y rola a la derecha según avanza la regata, así que el lado derecho del recorrido suele compensar (al sur del ecuador rola a la izquierda, y compensa el izquierdo).', 'Auf dem Vorwindkurs ist es umgekehrt. Ein Raumer lässt dich anluven, weg von der Bahnmarke, um denselben Winkel zum Wind zu halten; halse, und der Dreher zeigt wieder auf die Bahnmarke. An einem Seebrisentag baut der Wind im Verlauf der Regatta auch auf und dreht nach rechts, deshalb lohnt sich oft die rechte Seite der Bahn (südlich des Äquators dreht er nach links, und die linke Seite lohnt sich).', 'Pupada işler tersine çalışır. Lehte dönüş, rüzgâra karşı aynı açıyı korumak için seni şamandıradan uzağa orsalatır; kavança at, dönüş seni yeniden şamandıraya yöneltir. Deniz meltemi olan bir günde rüzgâr yarış ilerledikçe ayrıca güçlenir ve sağa döner; bu yüzden parkurun sağ tarafı çoğu zaman kazandırır (ekvatorun güneyinde sola döner ve sol taraf kazandırır).', 'Au portant, c’est l’inverse. Une adonnante te fait lofer, loin de la bouée, pour garder le même angle au vent ; empanne et la bascule te remet le cap sur la bouée. Les jours de brise thermique, le vent forcit aussi et tourne à droite au fil de la régate, si bien que le côté droit du plan d’eau paie souvent (au sud de l’équateur, il tourne à gauche, et c’est le côté gauche qui paie).'),
      ] },
    ],
    more: [
      { label: t('How to play: wind that won’t sit still', 'Как играть: ветер, который не стоит на месте', 'Cómo jugar: un viento que no se queda quieto', 'So spielst du: Wind, der nicht stillhält', 'Nasıl oynanır: yerinde durmayan rüzgâr', 'Comment jouer : un vent qui ne tient pas en place'), href: '/help#h-wind' },
      { label: t('FAQ: sailing the boat', 'Вопросы и ответы: управление лодкой', 'FAQ: navegar el barco', 'FAQ: das Boot segeln', 'SSS: tekneyi yelkenle sürmek', 'FAQ : mener le bateau'), href: '/faq' },
    ],
    try: { label: t('Sail today’s race', 'Пройди гонку дня', 'Navega la regata del día', 'Die Regatta des Tages segeln', 'Günün yarışına çık', 'Cours la régate du jour'), href: '/race', text: t(
      'Shifts of ten degrees and more, gusts and lulls, five boats to beat to the windward mark.',
      'Сдвиги ветра на десять градусов и больше, порывы и затишья и пять лодок, которых надо обойти к верхнему знаку.', 'Roladas de diez grados y más, rachas y calmas, cinco barcos a batir hasta la baliza de barlovento.', 'Dreher von zehn Grad und mehr, Böen und Flauten, fünf Boote, die du bis zur Luvtonne schlagen musst.', 'On dereceye varan ve daha fazla dönüşler, hamleler ve rüzgâr kesilmeleri, rüzgârüstü şamandırasına kadar yenilecek beş tekne.', 'Des bascules de dix degrés et plus, des risées et des molles, cinq bateaux à battre jusqu’à la bouée au vent.') },
  };
}
